1	import { db } from "./db";
2	import { pveFor } from "./proxmox";
3	import { effectiveDiskGB } from "./extra-disk";
4	
5	/**
6	 * Host capacity accounting for the deploy flow.
7	 *
8	 * We oversell RAM (the scarce resource) by a factor, but never past the
9	 * host's physical RAM minus a reserve for the hypervisor itself. Disk on
10	 * `vmdata` is large relative to plan sizes, so RAM is the binding constraint.
11	 *
12	 * All values are overridable via env so staging/prod can differ without code
13	 * changes; the defaults match the production KS-GAME box (64 GB RAM).
14	 */
15	export const HOST_RAM_MB = Number(process.env.NXEON_HOST_RAM_MB ?? 64000);
16	export const HOST_RAM_RESERVE_MB = Number(process.env.NXEON_HOST_RAM_RESERVE_MB ?? 8000);
17	export const RAM_OVERSELL_FACTOR = Number(process.env.NXEON_RAM_OVERSELL ?? 1.5);
18	
19	/**
20	 * Usable NVMe VM-disk pool in GB, used as a fallback when the live Proxmox
21	 * storage total can't be read. Unlike RAM we do NOT oversell disk — thin
22	 * provisioning already lets guests share the pool, so we commit against the
23	 * real pool size minus a safety margin.
24	 */
25	export const HOST_DISK_GB = Number(process.env.NXEON_HOST_DISK_GB ?? 800);
26	/** Fraction of usable disk we allow to be committed before refusing deploys. */
27	export const DISK_SAFETY_RATIO = Number(process.env.NXEON_DISK_SAFETY ?? 0.9);
28	
29	/** Effective committable RAM ceiling in MB after reserve + oversell. */
30	export function ramCeilingMB(): number {
31	  return Math.max(0, (HOST_RAM_MB - HOST_RAM_RESERVE_MB) * RAM_OVERSELL_FACTOR);
32	}
33	
34	export type CapacitySnapshot = {
35	  committedRamMB: number;
36	  committedDiskGB: number;
37	  ceilingRamMB: number;
38	  serverCount: number;
39	  /** 0..1 fraction of the RAM ceiling already committed. */
40	  ramUtilization: number;
41	  /** true once committed RAM is within 15% of the ceiling. */
42	  nearCapacity: boolean;
43	};
44	
45	/** Sum committed RAM/disk across all servers that are not being torn down. */
46	export async function capacitySnapshot(): Promise<CapacitySnapshot> {
47	  const servers = await db.server.findMany({
48	    where: { status: { not: "DELETING" } },
49	    select: { extraDiskGB: true, plan: { select: { ramMB: true, diskGB: true } } },
50	  });
51	  const committedRamMB = servers.reduce((sum, s) => sum + s.plan.ramMB, 0);
52	  const committedDiskGB = servers.reduce((sum, s) => sum + effectiveDiskGB(s.plan.diskGB, s.extraDiskGB), 0);
53	  const ceilingRamMB = ramCeilingMB();
54	  const ramUtilization = ceilingRamMB > 0 ? committedRamMB / ceilingRamMB : 1;
55	  return {
56	    committedRamMB,
57	    committedDiskGB,
58	    ceilingRamMB,
59	    serverCount: servers.length,
60	    ramUtilization,
61	    nearCapacity: ramUtilization >= 0.85,
62	  };
63	}
64	
65	/**
66	 * Would deploying `planId` push committed RAM past the oversell ceiling?
67	 * Returns { ok:false, reason } when the host cannot take the new server.
68	 */
69	export async function capacityCheck(planId: string): Promise<{ ok: boolean; reason?: string }> {
70	  const plan = await db.plan.findUnique({ where: { id: planId }, select: { ramMB: true, name: true } });
71	  if (!plan) return { ok: false, reason: "Plan not found." };
72	
73	  const snap = await capacitySnapshot();
74	  const projected = snap.committedRamMB + plan.ramMB;
75	  if (projected > snap.ceilingRamMB) {
76	    return {
77	      ok: false,
78	      reason:
79	        "The host is at capacity — not enough RAM headroom to deploy this plan right now. " +
80	        "Please try a smaller plan or contact support.",
81	    };
82	  }
83	  return { ok: true };
84	}
85	
86	/**
87	 * Would committing `addDiskGB` more of VM disk overflow the node's usable
88	 * storage? Mirrors `capacityCheck` but for disk: sums committed plan disk on
89	 * the node and compares against the usable NVMe pool times a safety ratio.
90	 *
91	 * Usable pool size is read live from Proxmox (`storageNvme` status) when the
92	 * node is reachable, falling back to `HOST_DISK_GB`. Pass `nodeId = null` to
93	 * check against all non-deleting servers / the primary node.
94	 */
95	export async function diskCapacityCheck(
96	  nodeId: string | null | undefined,
97	  addDiskGB: number
98	): Promise<{ ok: boolean; reason?: string }> {
99	  const servers = await db.server.findMany({
100	    where: { status: { not: "DELETING" }, ...(nodeId ? { nodeId } : {}) },
101	    select: { extraDiskGB: true, plan: { select: { diskGB: true } } },
102	  });
103	  // Committed disk counts the EFFECTIVE size of every server (plan + purchased
104	  // extra), otherwise expansions would silently oversubscribe the pool.
105	  const committedDiskGB = servers.reduce((sum, s) => sum + effectiveDiskGB(s.plan.diskGB, s.extraDiskGB), 0);
106	
107	  // Resolve usable pool size — prefer the live Proxmox NVMe pool total.
108	  let usableGB = HOST_DISK_GB;
109	  try {
110	    const n = nodeId
111	      ? await db.node.findUnique({ where: { id: nodeId } })
112	      : await db.node.findFirst({ where: { isPrimary: true } });
113	    if (n) {
114	      const client = pveFor({
115	        apiUrl: n.apiUrl,
116	        pveNode: n.pveNode,
117	        tokenId: n.tokenId,
118	        tokenSecret: n.tokenSecret,
119	      });
120	      const st = await client.get(`/nodes/${n.pveNode}/storage/${n.storageNvme}/status`);
121	      const totalGB = Number(st?.total ?? 0) / 1024 ** 3;
122	      if (totalGB > 0) usableGB = totalGB;
123	    }
124	  } catch {
125	    // Proxmox unreachable — fall back to the configured HOST_DISK_GB.
126	  }
127	
128	  const ceilingGB = usableGB * DISK_SAFETY_RATIO;
129	  const projected = committedDiskGB + addDiskGB;
130	  if (projected > ceilingGB) {
131	    return {
132	      ok: false,
133	      reason:
134	        "Not enough disk headroom on this node to deploy this plan right now. " +
135	        "Please choose a smaller disk or contact support.",
136	    };
137	  }
138	  return { ok: true };
139	}
