268	export async function vmStatus(vmid: number): Promise<any> {
269	  return pve.get(`/nodes/${NODE}/qemu/${vmid}/status/current`);
270	}
271	
272	export async function nodeStatus(): Promise<any> {
273	  return pve.get(`/nodes/${NODE}/status`);
274	}
