280	/** Time-series metrics. timeframe: hour | day | week | month | year.
281	 *  Pass the server's node connection — vmids can collide across nodes, so a
282	 *  same-numbered VM on another node would otherwise leak that tenant's series. */
283	export async function vmRrd(vmid: number, timeframe = "hour", conn?: PveClient): Promise<any[]> {
284	  const c = conn ?? pve;
285	  const node = conn ? conn.node : NODE;
286	  return c.get(`/nodes/${node}/qemu/${vmid}/rrddata`, { timeframe, cf: "AVERAGE" });
287	}
288	
289	export async function nodeRrd(timeframe = "hour"): Promise<any[]> {
290	  return pve.get(`/nodes/${NODE}/rrddata`, { timeframe, cf: "AVERAGE" });
291	}
