293	// ---------------------------------------------------------------------------
294	// In-guest disk usage via the QEMU guest agent (get-fsinfo)
295	// ---------------------------------------------------------------------------
296	
297	/** Real filesystem usage as reported from *inside* the guest. */
298	export type GuestDiskUsage = { usedBytes: number; totalBytes: number };
299	
300	/** Any client exposing `get` (satisfied by `pve` and `pveFor(...)`). */
301	export type GuestAgentClient = {
302	  get: (path: string, params?: Record<string, any>) => Promise<any>;
303	};
304	
305	// Pseudo / virtual filesystems that don't represent real on-disk usage and must
306	// never be picked as the root filesystem. Matched against the fsinfo `type`.
307	const PSEUDO_FS_TYPES = new Set([
308	  "squashfs", "tmpfs", "devtmpfs", "overlay", "overlayfs", "vfat", "msdos",
309	  "proc", "sysfs", "cgroup", "cgroup2", "debugfs", "mqueue", "hugetlbfs",
310	  "fusectl", "pstore", "autofs", "binfmt_misc", "tracefs", "configfs",
311	  "securityfs", "ramfs", "nsfs", "efivarfs", "fuse.snapfuse", "iso9660",
312	]);
313	
314	/** Is this mountpoint one we should ignore even if the type looks real? */
315	function isIgnorableMount(mountpoint: string): boolean {
316	  const mp = String(mountpoint ?? "");
317	  return (
318	    mp === "/boot" ||
319	    mp.startsWith("/boot/") ||
320	    mp.startsWith("/snap") ||
321	    mp.startsWith("/var/lib/docker") ||
322	    mp.startsWith("/run") ||
323	    mp.startsWith("/dev") ||
324	    mp.startsWith("/sys") ||
325	    mp.startsWith("/proc")
326	  );
327	}
328	
329	/**
330	 * Query the QEMU guest agent's `get-fsinfo` and return the REAL root filesystem
331	 * usage (the entry mounted at "/", excluding pseudo/boot/loop filesystems).
332	 *
333	 * Proxmox RRD's `disk` field is 0 for QEMU VMs — the hypervisor can't see
334	 * in-guest usage — so this agent call is the only source of real used/total
335	 * bytes. Best-effort: returns null on any error or when the agent isn't ready
336	 * (never throws), so a missing agent degrades cleanly to the provisioned-size
337	 * fallback. In SANDBOX returns a synthetic, gently-varying realistic value.
338	 *
339	 * @param sandboxTotalBytes only used to size the synthetic sandbox value.
340	 */
341	export async function getGuestDiskUsage(
342	  client: GuestAgentClient,
343	  node: string,
344	  vmid: number,
345	  sandboxTotalBytes?: number
346	): Promise<GuestDiskUsage | null> {
347	  if (SANDBOX) {
348	    const total = sandboxTotalBytes && sandboxTotalBytes > 0 ? sandboxTotalBytes : 40 * 1024 ** 3;
349	    const base = 0.3 + (Math.abs(vmid) % 35) / 100; // 0.30..0.64
350	    const drift = 0.03 * Math.sin(Date.now() / (6 * 3600_000) + vmid); // slow ±3%
351	    const frac = Math.min(0.95, Math.max(0.05, base + drift));
352	    return { usedBytes: Math.round(total * frac), totalBytes: total };
353	  }
354	
355	  try {
356	    const res = await client.get(`/nodes/${node}/qemu/${vmid}/agent/get-fsinfo`);
357	    // The agent wraps the array in { result: [...] }; tolerate a bare array too.
358	    const list: any[] = Array.isArray(res?.result)
359	      ? res.result
360	      : Array.isArray(res)
361	        ? res
362	        : [];
363	    if (list.length === 0) return null;
364	
365	    const real = list.filter((fs) => {
366	      const type = String(fs?.type ?? "").toLowerCase();
367	      const mp = String(fs?.mountpoint ?? "");
368	      if (PSEUDO_FS_TYPES.has(type)) return false;
369	      if (isIgnorableMount(mp)) return false;
370	      const total = Number(fs?.["total-bytes"]);
371	      return Number.isFinite(total) && total > 0;
372	    });
373	    if (real.length === 0) return null;
374	
375	    // Prefer the real root filesystem; otherwise the largest real mount.
376	    const root =
377	      real.find((fs) => String(fs?.mountpoint) === "/") ??
378	      real.sort((a, b) => Number(b?.["total-bytes"]) - Number(a?.["total-bytes"]))[0];
379	
380	    const usedBytes = Number(root?.["used-bytes"]);
381	    const totalBytes = Number(root?.["total-bytes"]);
382	    if (!Number.isFinite(usedBytes) || !Number.isFinite(totalBytes) || totalBytes <= 0) {
383	      return null;
384	    }
385	    return { usedBytes, totalBytes };
386	  } catch {
387	    // Agent not installed / not ready / VM stopped / transient PVE error.
388	    return null;
389	  }
390	}
391	
392	/**
393	 * Wait until the QEMU guest agent answers, i.e. until the guest has genuinely
394	 * booted far enough to run software.
395	 *
396	 * WHY: `waitForTask(startUpid)` proves only that Proxmox ACCEPTED the start —
397	 * not that the guest booted, that cloud-init ran, or that sshd is listening. The
398	 * provision path used to write RUNNING and hand the customer a copy-pasteable
399	 * `ssh root@…` line on the strength of that task alone (M7 #10), which is why a
400	 * RUNNING server eight minutes old could still show "SSH command: provisioning…".
401	 *
402	 * Returns true only on a real reply. On timeout it returns FALSE rather than
403	 * throwing, so the caller can degrade its message honestly instead of failing a
404	 * server that is merely slow — a guest with no agent installed is a normal state
405	 * for some images, and calling that a provisioning failure would be its own lie.
406	 */
407	export async function waitForGuestAgent(
408	  client: GuestAgentClient,
409	  node: string,
410	  vmid: number,
411	  timeoutMs = 180_000,
412	  pollMs = 5_000
413	): Promise<boolean> {
414	  const deadline = Date.now() + timeoutMs;
415	  for (;;) {
416	    try {
417	      await client.get(`/nodes/${node}/qemu/${vmid}/agent/ping`);
418	      return true;
419	    } catch {
420	      /* agent not up yet */
421	    }
422	    if (Date.now() >= deadline) return false;
423	    await new Promise((r) => setTimeout(r, pollMs));
424	  }
425	}
