437	// ---------------------------------------------------------------------------
438	// Platform backups vs customer backups
439	// ---------------------------------------------------------------------------
440	//
441	// DATA LOSS PREVENTED (real, on this host, 2026-07-26): `scripts/backup-vms.sh`
442	// used to write the platform's own host-level disaster-recovery archives into the
443	// SAME Proxmox storage (`backup` -> /tank/backup/dump) that customers' on-demand
444	// backups land in, and `pruneBackups` below selected victims with nothing but
445	// `b.vmid === vmid`. So vmid 102 ended the 04:31 platform run holding two
446	// archives — the customer's own manual one from 2026-07-25 12:22 and the
447	// platform's 10 GB DR copy from 2026-07-26 04:31 — and the customer's very next
448	// click on "Create backup" (keep = CUSTOMER_BACKUP_KEEP = 2) would have deleted
449	// the platform's copy of their VM. Repeated across the fleet that silently
450	// destroys the entire bare-metal recovery set, one customer click at a time.
451	//
452	// The fix is three independent layers, in order of strength:
453	//
454	//  1. STRUCTURAL. `scripts/backup-vms.sh` now writes with `vzdump --dumpdir
455	//     /tank/backup/platform`, a directory that is NOT the `dump/` subdirectory of
456	//     any configured PVE storage. Proxmox only indexes `<storage-path>/dump`, so
457	//     platform archives have no `volid` at all: they cannot appear in the
458	//     `/storage/backup/content` listing this function iterates, and there is no
459	//     volid string that `DELETE /storage/backup/content/<volid>` could resolve to
460	//     them. Not "filtered out" — not addressable.
461	//  2. CHOKEPOINT. `deleteBackup` is the only function in the repo that issues a
462	//     storage-content DELETE (whole-repo grep: this file plus its single caller in
463	//     worker/index.ts). It re-derives protection for every volid immediately
464	//     before deleting and refuses on any of: the PVE `protected` attribute, the
465	//     platform notes marker, or the protection registry — and it fails CLOSED if
466	//     it cannot determine the answer.
467	//  3. MARKER + REGISTRY. If the platform job is ever pointed back at a shared PVE
468	//     storage (`NXEON_VM_BACKUP_STORAGE=backup`), it stamps each archive with
469	//     `--notes-template` carrying PLATFORM_BACKUP_MARKER and appends the volid to
470	//     PROTECTED_REGISTRY. Both are honoured below, which also covers the archives
471	//     already sitting in /tank/backup/dump from the 2026-07-26 04:31 run, written
472	//     before layer 1 existed.
473	
474	/** Where the platform's own whole-system vzdump archives live — outside every PVE storage. */
475	export const PLATFORM_BACKUP_DIR = process.env.NXEON_PLATFORM_BACKUP_DIR ?? "/tank/backup/platform";
476	
477	/**
478	 * Stamped into the vzdump notes of platform archives (see `--notes-template` in
479	 * scripts/backup-vms.sh). Customer retention must never delete an archive whose
480	 * notes contain this string.
481	 */
482	export const PLATFORM_BACKUP_MARKER = "NXEON-PLATFORM-BACKUP";
483	
484	/**
485	 * One volid per line. Maintained by scripts/backup-vms.sh; also seeded with any
486	 * pre-existing platform archives that were written into the shared storage before
487	 * the dumpdir split. Anything listed here is undeletable through this module.
488	 */
489	const PROTECTED_REGISTRY = `${PLATFORM_BACKUP_DIR}/PROTECTED-VOLIDS`;
490	
491	/**
492	 * Read the protection registry.
493	 *
494	 * Returns `null` when the registry exists but could not be read. Callers MUST
495	 * treat `null` as "protection state unknown" and refuse to delete: a transient
496	 * EIO on this file must not be the thing that lets a customer's prune wipe the
497	 * platform's recovery set. A registry that simply does not exist yet (fresh
498	 * install, platform job has never run) is a legitimate empty set — layer 1 means
499	 * there is nothing in the shared storage to protect in that case anyway.
500	 */
501	async function protectedVolids(): Promise<Set<string> | null> {
502	  const { readFile } = await import("node:fs/promises");
503	  try {
504	    const raw = await readFile(PROTECTED_REGISTRY, "utf8");
505	    return new Set(
506	      raw.split("\n").map((l) => l.trim()).filter((l) => l.length > 0 && !l.startsWith("#"))
507	    );
508	  } catch (e: any) {
509	    if (e?.code === "ENOENT") return new Set();
510	    console.error(`[proxmox] protection registry ${PROTECTED_REGISTRY} unreadable — refusing to prune`, e);
511	    return null;
512	  }
513	}
514	
515	/** Shape of one entry in `/nodes/<node>/storage/<sid>/content`. */
516	/**
517	 * Every backup archive the `backup` storage holds for one VMID, read through a
518	 * node-scoped client. This is the READ-BACK that `backupCreate` uses to prove an
519	 * archive actually exists: the vzdump task's exit status says the task ran, not
520	 * that a file landed. See worker/backup-schedule.ts (`freshBackupProof`) and
521	 * incident H4.
522	 */
523	export async function listBackupsOn(client: any, vmid: number): Promise<StorageBackupEntry[]> {
524	  const content: StorageBackupEntry[] = await client.get(
525	    `/nodes/${client.node}/storage/backup/content`,
526	    { content: "backup" }
527	  );
528	  return content.filter((b) => b.vmid === vmid && typeof b.volid === "string");
529	}
530	
531	export type StorageBackupEntry = {
532	  volid?: string;
533	  vmid?: number;
534	  ctime?: number;
535	  size?: number;
536	  notes?: string;
537	  protected?: boolean | number;
538	};
539	
540	/**
541	 * Is this archive one of the platform's own (i.e. never customer-prunable)?
542	 * Any single signal is enough — they are deliberately redundant.
543	 */
544	export function isPlatformArchive(b: StorageBackupEntry, registry: Set<string>): boolean {
545	  if (b.protected) return true;
546	  if (typeof b.notes === "string" && b.notes.includes(PLATFORM_BACKUP_MARKER)) return true;
547	  if (typeof b.volid === "string" && registry.has(b.volid)) return true;
548	  return false;
549	}
550	
551	/**
552	 * Delete one backup archive by its Proxmox volume id. `client` = the node's pve client.
553	 *
554	 * This is the ONLY storage-content DELETE in the codebase, so it is where the
555	 * "a customer can never delete a platform archive" invariant is enforced rather
556	 * than merely intended. It re-checks protection against the live hypervisor for
557	 * the exact volid being deleted — a caller that passed a stale or hand-crafted
558	 * volid cannot slip past it. Every uncertain outcome throws.
559	 */
560	export async function deleteBackup(client: any, volid: string): Promise<void> {
561	  // Only `<storage>:backup/<basename>` volids are deletable here. Rejecting
562	  // anything else keeps a malformed or path-traversing volid from ever reaching
563	  // the API, and keeps this function honest about what it operates on.
564	  const m = /^([A-Za-z0-9._-]+):backup\/([^/]+)$/.exec(volid);
565	  if (!m) throw new Error(`refusing to delete: '${volid}' is not a <storage>:backup/<file> volid`);
566	
567	  const registry = await protectedVolids();
568	  if (registry === null) {
569	    throw new Error(`refusing to delete ${volid}: platform protection registry unreadable`);
570	  }
571	  if (registry.has(volid)) {
572	    throw new Error(`refusing to delete ${volid}: listed in the platform protection registry`);
573	  }
574	
575	  // Ask the hypervisor about this exact volume. `notes` and `protected` are both
576	  // returned by the content-info endpoint (PVE::API2::Storage::Content). A failure
577	  // here means we do not know whether this is a platform archive, so we stop.
578	  let info: any;
579	  try {
580	    info = await client.get(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
581	  } catch (e) {
582	    throw new Error(`refusing to delete ${volid}: could not read its attributes (${e})`);
583	  }
584	  if (isPlatformArchive({ volid, notes: info?.notes, protected: info?.protected }, registry)) {
585	    throw new Error(`refusing to delete ${volid}: it is a platform (host-level) backup`);
586	  }
587	
588	  await client.del(`/nodes/${client.node}/storage/backup/content/${encodeURIComponent(volid)}`);
589	}
590	
591	/**
592	 * Retention for ONE CUSTOMER SERVER: keep only the newest `keep` archives that
593	 * belong to that customer, deleting the older ones (best-effort per file, oldest
594	 * first). Runs after every successful customer backup, and from the standalone
595	 * sweep in worker/backup-schedule.ts. Returns how many were deleted.
596	 *
597	 * Platform archives are excluded from the delete set AND from the retention
598	 * count. Counting them would be its own bug: with keep = 2, three platform
599	 * archives of a vmid would make every customer archive "older than the newest
600	 * two" and delete all of the customer's backups instead.
601	 */
602	export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
603	  const registry = await protectedVolids();
604	  if (registry === null) {
605	    // Fail closed: no retention this pass. Archives accumulating for one cycle is
606	    // recoverable; deleting the platform's only copy of a VM is not.
607	    console.error(`[proxmox] pruneBackups: protection state unknown, skipping prune for vmid ${vmid}`);
608	    return 0;
609	  }
610	
611	  const forVmid = await listBackupsOn(client, vmid);
612	  const shielded = forVmid.filter((b) => isPlatformArchive(b, registry));
613	  const mine = forVmid
614	    .filter((b) => !isPlatformArchive(b, registry))
615	    .sort((a, b) => (b.ctime ?? 0) - (a.ctime ?? 0));
616	
617	  if (shielded.length > 0) {
618	    console.log(
619	      `[proxmox] pruneBackups: vmid ${vmid} — ${shielded.length} platform archive(s) excluded from retention`
620	    );
621	  }
622	
623	  const toDelete = mine.slice(Math.max(0, keep));
624	  let deleted = 0;
625	  for (const b of toDelete) {
626	    try {
627	      await deleteBackup(client, b.volid!);
628	      deleted++;
629	    } catch (e) {
630	      console.error(`[proxmox] pruneBackups: failed to delete ${b.volid}`, e);
631	    }
632	  }
633	  return deleted;
634	}
635	
636	export async function storageStatus(storage: string): Promise<any> {
637	  return pve.get(`/nodes/${NODE}/storage/${storage}/status`);
638	}
