1	/**
2	 * Backup PROOF rules — the pure decision logic that stands between "the vzdump
3	 * task returned" and telling a customer they have a restore point.
4	 *
5	 * INCIDENT (customer-journey rehearsal 2026-07-26, finding H4): `lastAutoBackup`
6	 * was stamped at the moment the BACKUP_CREATE job row was ENQUEUED, and written
7	 * nowhere else. So "Last automatic backup: 2026-07-26 04:00 UTC" only ever meant
8	 * *a row was created*. vzdump could have failed every night for a month with no
9	 * alert, no failure notification, and the schedule marked satisfied — so the
10	 * retry was a full interval away and the customer found out at restore time, the
11	 * one moment it cannot be fixed. The deploy wizard SELLS this at the point of
12	 * sale ("Daily auto-backups · Nightly snapshots to separate storage for easy
13	 * restore").
14	 *
15	 * The rules now:
16	 *
17	 *   - `Server.lastAutoBackup` is a PROOF timestamp. It is written in exactly one
18	 *     place — `backupCreate` in worker/index.ts — after a storage-content read
19	 *     shows an archive for this VMID that was NOT there before the run and has
20	 *     size > 0. An exit code from the vzdump task is not evidence.
21	 *   - The sweep's anti-pile-up anchor is the last ATTEMPT, read from the Job
22	 *     table. That is a fact we can observe without claiming anything about the
23	 *     outcome.
24	 *   - Absence is rendered, not hidden: `backupScheduleHealth` is the single
25	 *     source of the sentence the customer reads under "Scheduled backups".
26	 *
27	 * Deterministic and dependency-free on purpose: no Prisma, no Proxmox, no clock
28	 * (every entry point takes `now`). Covered by test/backup-proof.test.ts.
29	 */
30	
31	// ---------------------------------------------------------------------------
32	// Proof
33	// ---------------------------------------------------------------------------
34	
35	/** The subset of a Proxmox storage-content row this module reasons about. */
36	export type BackupArchive = {
37	  volid?: string;
38	  vmid?: number;
39	  size?: number;
40	  ctime?: number;
41	};
42	
43	export type BackupProof =
44	  | { proven: true; volid: string; sizeBytes: number }
45	  | { proven: false; reason: string };
46	
47	/** Human-sized bytes for notification/log copy. */
48	export function humanBytes(n: number): string {
49	  if (!Number.isFinite(n) || n < 0) return "unknown size";
50	  const units = ["B", "KB", "MB", "GB", "TB"];
51	  let v = n;
52	  let i = 0;
53	  while (v >= 1024 && i < units.length - 1) {
54	    v /= 1024;
55	    i++;
56	  }
57	  return `${i === 0 ? v : v.toFixed(1)} ${units[i]}`;
58	}
59	
60	/**
61	 * Did THIS run demonstrably write a backup?
62	 *
63	 * Evidence is a volid present in `after` that was absent from `before`, carrying
64	 * a non-zero size. Set membership rather than a timestamp comparison on purpose:
65	 * `ctime` comes off the hypervisor and any window we computed would come off the
66	 * worker's clock, and skew between the two is exactly the kind of thing that
67	 * turns a proof back into a guess. A volid that was not there and now is cannot
68	 * be explained away by a clock.
69	 *
70	 * Every failure returns the reason AND the command an operator can run, because
71	 * "backup failed" with no next step is barely better than the silence it
72	 * replaced.
73	 */
74	export function freshBackupProof(opts: {
75	  vmid: number;
76	  before: readonly BackupArchive[];
77	  after: readonly BackupArchive[];
78	}): BackupProof {
79	  const { vmid } = opts;
80	  const check = `Check it yourself with: pvesm list backup --vmid ${vmid}`;
81	  const seen = new Set<string>();
82	  for (const b of opts.before) {
83	    if (b.vmid === vmid && typeof b.volid === "string") seen.add(b.volid);
84	  }
85	
86	  const fresh = opts.after.filter(
87	    (b) => b.vmid === vmid && typeof b.volid === "string" && !seen.has(b.volid)
88	  );
89	
90	  if (fresh.length === 0) {
91	    return {
92	      proven: false,
93	      reason:
94	        `the vzdump task finished but no new archive for VMID ${vmid} appeared in the ` +
95	        `"backup" storage, so nothing was written and there is no restore point from this run. ` +
96	        check,
97	    };
98	  }
99	
100	  // Prefer the largest new archive: if a run somehow left a truncated stub beside
101	  // a good one, the good one is the honest answer.
102	  const sized = fresh
103	    .filter((b) => typeof b.size === "number" && Number.isFinite(b.size))
104	    .sort((a, b) => (b.size ?? 0) - (a.size ?? 0));
105	
106	  if (sized.length === 0) {
107	    return {
108	      proven: false,
109	      reason:
110	        `a new archive for VMID ${vmid} appeared (${fresh[0].volid}) but the storage listing ` +
111	        `reported no size for it, so we cannot confirm it contains anything. ` +
112	        `Not recording a backup we cannot prove. ` +
113	        check,
114	    };
115	  }
116	
117	  const best = sized[0];
118	  if ((best.size ?? 0) <= 0) {
119	    return {
120	      proven: false,
121	      reason:
122	        `a new archive for VMID ${vmid} appeared (${best.volid}) but it is 0 bytes — ` +
123	        `an empty file is not a backup and would fail at restore time. ` +
124	        check,
125	    };
126	  }
127	
128	  return { proven: true, volid: best.volid!, sizeBytes: best.size! };
129	}
