93	function buildCloudInit(server: any): string {
94	  const addons = (server.addons ?? {}) as {
95	    malwareScanner?: boolean;
96	    dailyBackup?: boolean;
97	    docker?: boolean;
98	    claudeCode?: boolean;
99	  };
100	  const setup: string[] = [];
101	
102	  // Pre-bake Claude Code (Anthropic CLI) on every server unless explicitly opted
103	  // out. Customers SSH in and run `claude` using their own subscription or API
104	  // key — no setup on our side, zero token cost to us. Installs run in the
105	  // background (nohup below) so the VM still reports ready quickly.
106	  if (addons.claudeCode !== false) {
107	    setup.push(
108	      "# --- Nxeon: pre-install Claude Code (Anthropic CLI) ---",
109	      "(apt-get install -y git curl ca-certificates || dnf install -y git curl ca-certificates || true)",
110	      "if ! command -v node >/dev/null 2>&1; then " +
111	        "(curl -fsSL https://deb.nodesource.com/setup_20.x | bash - && apt-get install -y nodejs) || " +
112	        "(curl -fsSL https://rpm.nodesource.com/setup_20.x | bash - && dnf install -y nodejs) || " +
113	        "(apt-get install -y nodejs npm || true); fi",
114	      "npm install -g @anthropic-ai/claude-code || true",
115	      "command -v claude >/dev/null 2>&1 && echo 'Claude Code installed' >> /var/log/nxeon-setup.log || true",
116	    );
117	  }
118	
119	  if (addons.docker) setup.push("curl -fsSL https://get.docker.com | sh && systemctl enable --now docker");
120	  if (addons.malwareScanner)
121	    setup.push("(apt-get install -y clamav clamav-daemon || dnf install -y clamav) && (systemctl enable --now clamav-freshclam || true)");
122	  if (server.osTemplate.setupScript) setup.push(server.osTemplate.setupScript);
123	
124	  const script = ["#!/bin/bash", "set -x", ...setup].join("\n");
125	
126	  // A friendly first-login guide + MOTD banner pointing at the portal hub.
127	  const welcome = [
128	    "# Welcome to your Nxeon server",
129	    "",
130	    "## Build anything with Claude Code — it's already installed",
131	    "",
132	    "1. You're already logged in. Just run:",
133	    "",
134	    "   claude",
135	    "",
136	    "2. Sign in once — either with your Claude subscription (Pro/Max) or an",
137	    "   Anthropic API key. See the step-by-step guide with screenshots at:",
138	    "",
139	    "   https://nxeon.cloud/dashboard/claude-code",
140	    "",
141	    "3. Then describe what you want in plain English, for example:",
142	    '   "Build a modern website for my coffee shop with a menu and contact form,',
143	    '    then run it and tell me the URL to preview it."',
144	    "",
145	    "Copy-paste starter prompts (spa site, booking app, REST API, Discord bot,",
146	    "and 20+ more) and how-to guides live in your portal at the link above.",
147	    "",
148	    "Happy building!",
149	  ].join("\n");
150	
151	  const motd = [
152	    "#!/bin/sh",
153	    'if [ -t 1 ]; then',
154	    '  printf "\\n  \\033[1mNxeon\\033[0m — Claude Code is pre-installed on this server.\\n"',
155	    '  printf "  Run \\033[1mclaude\\033[0m to start building. Guide: https://nxeon.cloud/dashboard/claude-code\\n"',
156	    '  printf "  Full walkthrough: \\033[2m~/START-WITH-CLAUDE.md\\033[0m\\n\\n"',
157	    "fi",
158	  ].join("\n");
