160	  return `#cloud-config
161	package_update: true
162	packages:
163	  - qemu-guest-agent
164	ssh_pwauth: true
165	disable_root: false
166	write_files:
167	  - path: /etc/ssh/sshd_config.d/60-nxeon.conf
168	    permissions: "0644"
169	    content: |
170	      PermitRootLogin yes
171	      PasswordAuthentication yes
172	  - path: /root/START-WITH-CLAUDE.md
173	    permissions: "0644"
174	    content: |
175	${indentBlock(welcome, 6)}
176	  - path: /etc/profile.d/nxeon-welcome.sh
177	    permissions: "0755"
178	    content: |
179	${indentBlock(motd, 6)}
180	  - path: /root/nxeon-setup.sh
181	    permissions: "0755"
182	    content: |
183	${indentBlock(script, 6)}
184	runcmd:
185	  - systemctl enable --now qemu-guest-agent
186	  - systemctl restart ssh || systemctl restart sshd
187	  - nohup /root/nxeon-setup.sh > /var/log/nxeon-setup.log 2>&1 &
188	`;
