194	async function provision(job: Job) {
195	  const server = await loadServer(job);
196	  await db.server.update({ where: { id: server.id }, data: { status: "PROVISIONING" } });
197	
198	  if (SANDBOX) {
199	    // Simulate provisioning entirely via DB writes — no Proxmox clone/config/
200	    // resize/start, no IPAM/OVH allocation, no cloud-init snippet write.
201	    const vmid = server.vmid ?? (990000 + (await db.server.count()));
202	    const password = generatePassword();
203	    const ip = sandboxIp(vmid);
204	    await db.server.update({
205	      where: { id: server.id },
206	      data: { vmid, ipAddress: ip, sshPort: null, rootPassword: null, rootPasswordEnc: encryptSecret(password), status: "RUNNING" },
207	    });
208	    await notify(
209	      server.userId,
210	      `Server ${server.hostname} is ready`,
211	      `Sandbox server provisioned (no real VM was created). ssh root@${ip}`,
212	      `/dashboard/servers/${server.id}`
213	    );
214	    return;
215	  }
216	
217	  const { conn, row: nodeRow } = await nodeFor(server);
218	  const storage = server.plan.storageTier === "hdd"
219	    ? nodeRow?.storageHdd ?? "vmdata-hdd"
220	    : nodeRow?.storageNvme ?? "vmdata";
221	
222	  const vmid = server.vmid ?? (await conn.nextVmid());
223	  const password = generatePassword();
224	
225	  // Dedicated public IPv4 (OVH failover + Virtual MAC on the public bridge) vs shared NAT.
226	  // Default: every new server pulls a dedicated IP from the pool; if the pool is
227	  // empty (or OVH isn't configured) it transparently falls back to shared NAT.
228	  let dedicated: { address: string; virtualMac: string; gateway: string } | null = null;
229	  const { getSettingBool: _settingBool } = await import("../lib/settings");
230	  const wantDedicated = server.wantsDedicatedIp || (await _settingBool("dedicated_ip_default", true));
231	  if (wantDedicated && ovhConfigured()) {
232	    try {
233	      // Idempotent: on a PROVISION retry (VM may already exist) this returns the
234	      // server's already-ASSIGNED IP rather than claiming a second pool IP.
235	      dedicated = await allocateDedicatedIp(server.id, vmid);
236	    } catch (e) {
237	      console.error("[worker] dedicated IP allocation failed, falling back to NAT", e);
238	    }
239	  }
240	  // Node-aware + transactionally-claimed allocation (passing the server id enables
241	  // the claim path, so two concurrent provisions can't pick the same IP/port).
242	  const ip = dedicated ? dedicated.address : (server.ipAddress ?? (await allocateIp(server.nodeId, server.id)));
243	  const sshPort = dedicated ? null : (server.sshPort ?? (await allocateSshPort(server.nodeId, server.id)));
244	
245	  await db.server.update({
246	    where: { id: server.id },
247	    data: { vmid, ipAddress: ip, sshPort, rootPassword: null, rootPasswordEnc: encryptSecret(password) },
248	  });
249	
250	  const baseVmid = server.osTemplate.baseVmid ?? server.osTemplate.vmid;
251	  // PROVISION must be re-runnable. `vmid` is persisted BEFORE the clone, so a retry
252	  // (worker restart mid-clone, or any transient failure in the steps below) would
253	  // re-issue a clone onto an id that now exists — Proxmox rejects it and all 3
254	  // attempts fail identically, stranding a half-built VM in ERROR. Everything after
255	  // the clone is idempotent, so skip it when the VM is already present.
256	  let vmAlreadyExists = false;
257	  try {
258	    await conn.vmStatus(vmid);
259	    vmAlreadyExists = true;
260	  } catch {
261	    vmAlreadyExists = false;
262	  }
263	  if (vmAlreadyExists) {
264	    console.log(`[worker] vm ${vmid} already exists — skipping clone (idempotent retry)`);
265	  } else {
266	    const cloneUpid = await conn.post(`/nodes/${conn.node}/qemu/${baseVmid}/clone`, {
267	      newid: vmid,
268	      name: server.hostname,
269	      full: 1,
270	      storage,
271	    });
272	    await conn.waitForTask(cloneUpid, 600_000);
273	  }
274	
275	  // Per-server cloud-init snippet (base + panel/app install + add-ons).
276	  //
277	  // This write used to be `.catch`'d to a console line (M7 #10). It must not be:
278	  // the very next config POST sets `cicustom: vendor=…/nxeon-<vmid>.yaml`, so a
279	  // failed write hands the VM a vendor-data file that does not exist. Root SSH
280	  // config, the guest agent, the setup script, START-WITH-CLAUDE.md and the MOTD
281	  // all silently vanish, and the customer is still told the server is ready.
282	  // Failing here is recoverable — the job retries, and the clone above is
283	  // idempotent. Continuing is not.
284	  const snippet = buildCloudInit(server);
285	  try {
286	    await writeFile(`${SNIPPET_DIR}/nxeon-${vmid}.yaml`, snippet, "utf8");
287	  } catch (e: any) {
288	    throw new Error(
289	      `could not write the cloud-init snippet ${SNIPPET_DIR}/nxeon-${vmid}.yaml (${e?.message ?? e}). ` +
290	        `The VM would boot with no root password, no SSH key and no setup script, so provisioning ` +
291	        `stopped here rather than reporting a server that would not be usable.`
292	    );
293	  }
294	
295	  const keys = await db.sshKey.findMany({ where: { userId: server.userId } });
296	  const sshkeys = keys.length
297	    ? encodeURIComponent(keys.map((k) => k.publicKey.trim()).join("\n"))
298	    : undefined;
299	  const cfg: Record<string, any> = {
300	    cores: server.plan.cpuCores,
301	    memory: server.plan.ramMB,
302	    ciuser: "root",
303	    cipassword: password,
304	    sshkeys,
305	    nameserver: "1.1.1.1 8.8.8.8",
306	    onboot: 1,
307	    cicustom: `vendor=${SNIPPET_STORAGE}:snippets/nxeon-${vmid}.yaml`,
308	    tags: `${process.env.NXEON_TAG ?? "nxeon"};user-${server.userId.slice(0, 8)}`,
309	  };
310	  if (dedicated) {
311	    // Public bridge + OVH Virtual MAC; failover IP as /32 with the host's OVH gateway.
312	    cfg.net0 = `virtio=${dedicated.virtualMac},bridge=vmbr0`;
313	    cfg.ipconfig0 = `ip=${dedicated.address}/32,gw=${dedicated.gateway}`;
314	  } else {
315	    // Node-aware gateway: a second node with a different subnet must not get the primary's gateway.
316	    cfg.ipconfig0 = `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`;
317	  }
318	  await conn.post(`/nodes/${conn.node}/qemu/${vmid}/config`, cfg);
319	
320	  // Provision at the EFFECTIVE size: the plan's allowance plus any extra disk the
321	  // customer bought as a deploy-time upsell, so the VM is born the right size and
322	  // no separate DISK_EXPAND job is needed on a fresh order.
323	  await conn.put(`/nodes/${conn.node}/qemu/${vmid}/resize`, {
324	    disk: "scsi0",
325	    size: `${effectiveDiskGB(server.plan.diskGB, server.extraDiskGB)}G`,
326	  });
327	
328	  // Port forwarding is what makes the `ssh root@host -p <port>` line below true
329	  // for a NAT server. If it cannot be proved, the readiness message says so
330	  // instead of printing a command that will hang (H5 + M7 #10). Not fatal: the
331	  // VM itself is fine and a failed PROVISION would flip it to ERROR and release
332	  // its IP, which is a worse outcome than a missing forward.
333	  let natError: Error | null = null;
334	  if (!SANDBOX && !dedicated) natError = await syncPortForwardsBestEffort(`provision ${server.hostname}`);
335	
336	  const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
337	  await conn.waitForTask(startUpid);
338	
339	  // `waitForTask` proves Proxmox accepted the start, nothing more. Ask the guest
340	  // agent whether the machine actually booted before calling it ready (M7 #10).
341	  // A false here is reported, never downgraded into silence.
342	  const booted = SANDBOX ? true : await waitForGuestAgent(conn, conn.node, vmid);
343	
344	  await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
345	  const isImage = server.osTemplate.category !== "PLAIN_OS";
346	  const sshLine = dedicated
347	    ? `ssh root@${dedicated.address}`
348	    : `ssh root@${server.node?.publicIp ?? process.env.PUBLIC_IP} -p ${sshPort}`;
349	
350	  const caveats: string[] = [];
351	  if (natError) {
352	    caveats.push(
353	      `Port forwarding could NOT be confirmed for this server, so the SSH command above may not connect yet — ` +
354	        `we are not going to pretend otherwise. Support has been alerted (${natError.message.slice(0, 200)}).`
355	    );
356	  }
357	  if (!booted) {
358	    caveats.push(
359	      "The hypervisor started the VM, but its guest agent has not answered yet, so we cannot confirm the " +
360	        "operating system finished booting. Give it a few more minutes; if the SSH command still fails, open a ticket."
361	    );
362	  }
363	  const body = [
364	    isImage ? `${server.osTemplate.name} is installing in the background (a few minutes). ${sshLine}` : sshLine,
365	    ...caveats,
366	  ].join(" — ");
367	  await notify(
368	    server.userId,
369	    // Never assert "ready" for something we could not verify.
370	    caveats.length ? `Server ${server.hostname} is up, with caveats` : `Server ${server.hostname} is ready`,
371	    body,
372	    `/dashboard/servers/${server.id}`
373	  );
374	}
