409	async function remove(job: Job) {
410	  const server = await loadServer(job);
411	  const { conn } = await nodeFor(server);
412	  if (!SANDBOX && server.vmid) {
413	    try {
414	      await destroyVm(conn, server.vmid);
415	    } catch (e: any) {
416	      // VM may never have been created; only swallow "does not exist"
417	      if (!String(e?.body ?? e?.message).includes("does not exist")) throw e;
418	    }
419	    // Best-effort: remove the per-server cloud-init snippet
420	    await unlink(`${SNIPPET_DIR}/nxeon-${server.vmid}.yaml`).catch(() => {});
421	  }
422	  // Return any dedicated IP to the pool (deletes the OVH Virtual MAC).
423	  if (!SANDBOX) await releaseDedicatedIp(server.id).catch((e) => console.error("[worker] release dedicated IP failed", e));
424	  // Any block-storage volume disk (vm-<vmid>-disk-N) was purged with the VM above.
425	  // Volume.server is SetNull, so the rows would otherwise survive with a dead
426	  // diskName and keep billing forever. Remove them and notify the owner. (The
427	  // reinstall guard already blocks the accidental case; a full server delete is an
428	  // intentional teardown, so we drop the volumes with it.)
429	  const orphanVolumes = await db.volume.findMany({ where: { serverId: server.id } });
430	  if (orphanVolumes.length > 0) {
431	    await db.volume.deleteMany({ where: { serverId: server.id } });
432	    for (const v of orphanVolumes) {
433	      await notify(
434	        v.userId,
435	        `Volume "${v.name}" was removed`,
436	        `${v.sizeGB} GB block storage was deleted along with server ${server.hostname}. Billing for it has stopped.`,
437	        "/dashboard/volumes",
438	      ).catch(() => {});
439	    }
440	  }
441	  // Detach this DELETE job (and any siblings) from the server FIRST, otherwise the
442	  // server.delete cascade removes THIS running Job row — the success-path
443	  // `job.update({id})` then throws P2025 and escapes runJob. Null serverId instead.
444	  await db.job.updateMany({ where: { serverId: server.id }, data: { serverId: null } });
445	  await db.server.delete({ where: { id: server.id } });
446	  // Best-effort BY NECESSITY: the server row is gone, so a throw here re-queues
447	  // DELETE, which then dies on "Server not found" and the sync is never retried
448	  // (H5's aggravating factor). The failure is logged in full rather than hidden.
449	  if (!SANDBOX) await syncPortForwardsBestEffort(`delete ${server.hostname}`);
450	}

450	}
