452	async function reinstall(job: Job) {
453	  const server = await loadServer(job);
454	  if (SANDBOX) {
455	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
456	    await notify(
457	      server.userId,
458	      `Server ${server.hostname} reinstalled (sandbox)`,
459	      "The sandbox server was reinstalled (no real VM was touched).",
460	      `/dashboard/servers/${server.id}`
461	    );
462	    return;
463	  }
464	  // DATA SAFETY (critical): a reinstall destroys the VM, and `destroyVm` runs
465	  // `qm destroy` with { "destroy-unreferenced-disks": 1, purge: 1 } — which wipes
466	  // EVERY disk the vmid owns, including attached block-storage Volume disks
467	  // (scsi1+, `vmdata:vm-<vmid>-disk-N`). A disk named `vm-<vmid>-disk-N` is owned
468	  // by that vmid, and both purge and the default destroy (which removes disks
469	  // referenced in config, incl. detached `unusedN` entries) delete it; there is no
470	  // Proxmox API to selectively spare it, and the reinstall re-clones onto the SAME
471	  // vmid, so we cannot GUARANTEE such a disk survives the destroy. Rather than risk
472	  // wiping a customer's data, BLOCK the reinstall until the volume(s) are detached.
473	  // Detaching moves the disk to an "unused" entry (data preserved on storage) and it
474	  // can be re-attached after the reinstall. This runs BEFORE any status change or
475	  // destructive call, so a blocked reinstall touches nothing.
476	  //
477	  // Match on `serverId` ALONE — NOT `status: "ATTACHED"`. Detaching keeps
478	  // `serverId` set (see worker/volumes.ts) so the volume can be re-attached, and
479	  // the disk remains owned by this vmid as an `unusedN` entry. PVE's destroy_vm
480	  // passes `include_unused => 1`, so it frees those too. Filtering on ATTACHED
481	  // let the worst path through: fill a volume, Detach (the UI says "Data is
482	  // preserved."), Reinstall — guard sees nothing attached, purge takes the data.
483	  // Detaching is therefore NOT sufficient protection, and telling the customer to
484	  // detach was wrong advice; they must delete the volume (which destroys just
485	  // that disk, deliberately) or move it to another server first.
486	  const pinnedVolumes = await db.volume.findMany({
487	    where: { serverId: server.id },
488	  });
489	  // Sandbox volumes have no real disk, so they cannot be purged and must not block.
490	  const realPinned = pinnedVolumes.filter(
491	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
492	  );
493	  if (realPinned.length > 0) {
494	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
495	    throw new Error(
496	      `Remove your data volume(s) before reinstalling to protect their data: ${names}. ` +
497	        `Reinstalling purges every disk this server owns — including detached volumes ` +
498	        `that are still assigned to it — and that cannot be undone.`
499	    );
500	  }
501	
502	  const { conn } = await nodeFor(server);
503	  await db.server.update({ where: { id: server.id }, data: { status: "REINSTALLING" } });
504	  if (server.vmid) await destroyVm(conn, server.vmid);
505	  await provision(job);
506	}
