508	async function suspend(job: Job, unsuspend: boolean) {
509	  const server = await loadServer(job);
510	  if (SANDBOX) {
511	    if (unsuspend) {
512	      await db.server.update({ where: { id: server.id }, data: { status: "RUNNING", suspendedNote: null, suspendReason: null } });
513	    } else {
514	      await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
515	    }
516	    return;
517	  }
518	  const { conn, row: nodeRow } = await nodeFor(server);
519	  if (unsuspend) {
520	    // The dedicated IP was returned to the pool while suspended — re-allocate one
521	    // and reconfigure the public network before starting the VM back up.
522	    if (server.vmid) {
523	      const { getSettingBool: _sb } = await import("../lib/settings");
524	      const wantDedicated = server.wantsDedicatedIp || (await _sb("dedicated_ip_default", true));
525	      const alreadyHas = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
526	      let reconfigured = alreadyHas ? true : false;
527	      if (wantDedicated && ovhConfigured() && !alreadyHas) {
528	        try {
529	          const d = await allocateDedicatedIp(server.id, server.vmid);
530	          if (d) {
531	            await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
532	              net0: `virtio=${d.virtualMac},bridge=vmbr0`,
533	              ipconfig0: `ip=${d.address}/32,gw=${d.gateway}`,
534	            });
535	            await db.server.update({ where: { id: server.id }, data: { ipAddress: d.address, sshPort: null } });
536	            reconfigured = true;
537	          }
538	        } catch (e) {
539	          console.error("[worker] re-allocate dedicated IP on unsuspend failed; falling back to NAT", e);
540	        }
541	      }
542	      // If we couldn't (or didn't) give it a dedicated IP, its net0 still points at
543	      // the Virtual MAC + failover IP that suspend released back to the pool — that
544	      // IP may now belong to another server. Reconfigure onto shared NAT so it boots
545	      // with a valid, non-conflicting network instead of a dead public config.
546	      if (!reconfigured) {
547	        try {
548	          const ip = server.ipAddress ?? (await allocateIp(server.nodeId, server.id));
549	          const sshPort = server.sshPort ?? (await allocateSshPort(server.nodeId, server.id));
550	          await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
551	            net0: `virtio,bridge=${nodeRow?.bridge ?? "vmbr1"}`,
552	            ipconfig0: `ip=${ip}/24,gw=${gatewayIp(nodeRow?.subnetPrefix)}`,
553	          });
554	          await db.server.update({ where: { id: server.id }, data: { ipAddress: ip, sshPort } });
555	        } catch (e) {
556	          console.error("[worker] NAT fallback on unsuspend failed", e);
557	        }
558	      }
559	    }
560	    await db.server.update({ where: { id: server.id }, data: { status: "STOPPED", suspendedNote: null, suspendReason: null } });
561	    // Not fatal to the unsuspend itself (the customer is paid up and the VM must
562	    // come back), but never silent: an unproved sync is logged with its reason.
563	    if (!SANDBOX) await syncPortForwardsBestEffort(`unsuspend ${server.hostname}`);
564	    const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
565	    await conn.waitForTask(upid);
566	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
567	  } else {
568	    try {
569	      const upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
570	      await conn.waitForTask(upid);
571	    } catch { /* may already be stopped */ }
572	    await db.server.update({ where: { id: server.id }, data: { status: "SUSPENDED" } });
573	    if (!SANDBOX) await syncPortForwardsBestEffort(`suspend ${server.hostname}`);
574	    // Return the dedicated IP to the pool while the server is suspended, so it
575	    // can be handed to a paying server. Re-allocated on unsuspend.
576	    if (ovhConfigured()) {
577	      try {
578	        const had = await db.dedicatedIp.findFirst({ where: { serverId: server.id } });
579	        if (had) {
580	          await releaseDedicatedIp(server.id);
581	          // MUST also clear the address off the server: `Server.ipAddress` is UNIQUE,
582	          // so leaving the released IP here makes the next server that claims it fail
583	          // with P2002 — that server then silently lands on NAT while its OVH Virtual
584	          // MAC stays allocated and billable. (NAT servers keep their private IP.)
585	          await db.server.update({
586	            where: { id: server.id },
587	            data: { ipAddress: null, ipv6: null },
588	          });
589	        }
590	      } catch (e) {
591	        console.error("[worker] release dedicated IP on suspend failed", e);
592	      }
593	    }
594	  }
595	}
