605	async function resize(job: Job) {
606	  const server = await loadServer(job);
607	  const payload = (job.payload ?? {}) as { planId?: string };
608	  const newPlan = await db.plan.findUnique({ where: { id: payload.planId ?? "" } });
609	  if (!newPlan) throw new Error("resize: target plan not found");
610	  if (newPlan.diskGB < server.plan.diskGB) throw new Error("resize: disk can only grow");
611	
612	  // Any separately-purchased extra disk is ADDITIVE to whichever plan the server
613	  // sits on, so it survives the plan change untouched — `Server.extraDiskGB` is
614	  // never written here. Sizes below are therefore always the EFFECTIVE size
615	  // (new plan + extra); using the bare plan size would ask Proxmox to SHRINK the
616	  // disk of any server carrying extra storage, and the resize would hard-fail.
617	  const newTotalDiskGB = effectiveDiskGB(newPlan.diskGB, server.extraDiskGB);
618	  const currentTotalDiskGB = effectiveDiskGB(server.plan.diskGB, server.extraDiskGB);
619	  const diskLine =
620	    server.extraDiskGB > 0
621	      ? `${newTotalDiskGB} GB disk (${newPlan.diskGB} GB plan + ${server.extraDiskGB} GB added storage)`
622	      : `${newPlan.diskGB} GB disk`;
623	
624	  if (SANDBOX) {
625	    await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
626	    await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
627	      `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
628	      `/dashboard/servers/${server.id}`);
629	    return;
630	  }
631	
632	  const { conn } = await nodeFor(server);
633	  const wasRunning = server.status === "RUNNING";
634	  await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/config`, {
635	    cores: newPlan.cpuCores,
636	    memory: newPlan.ramMB,
637	  });
638	  if (newTotalDiskGB > currentTotalDiskGB) {
639	    await conn.put(`/nodes/${conn.node}/qemu/${server.vmid}/resize`, {
640	      disk: "scsi0",
641	      size: `${newTotalDiskGB}G`,
642	    });
643	  }
644	  await db.server.update({ where: { id: server.id }, data: { planId: newPlan.id } });
645	  // CPU/RAM changes need a power cycle to apply
646	  if (wasRunning) {
647	    try {
648	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/shutdown`, { timeout: 60 });
649	      await conn.waitForTask(stopUpid, 120_000);
650	    } catch {
651	      const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/stop`, {});
652	      await conn.waitForTask(stopUpid);
653	    }
654	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
655	    await conn.waitForTask(startUpid);
656	  }
657	  await notify(server.userId, `Server ${server.hostname} resized to ${newPlan.name}`,
658	    `${newPlan.cpuCores} vCPU / ${newPlan.ramMB / 1024} GB RAM / ${diskLine}`,
659	    `/dashboard/servers/${server.id}`);
660	}
