662	async function snapshotOp(job: Job, op: "create" | "delete" | "rollback") {
663	  const server = await loadServer(job);
664	  const payload = (job.payload ?? {}) as { name?: string };
665	  const name = (payload.name ?? "").replace(/[^a-zA-Z0-9_]/g, "").slice(0, 40);
666	  if (!name) throw new Error("snapshot: invalid name");
667	  if (SANDBOX) {
668	    await notify(
669	      server.userId,
670	      `Snapshot ${op} (sandbox): ${name}`,
671	      `Sandbox snapshot ${op} completed (no real VM was touched).`,
672	      `/dashboard/servers/${server.id}`
673	    );
674	    return;
675	  }
676	  const { conn } = await nodeFor(server);
677	  let upid: string;
678	  if (op === "create") {
679	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot`, { snapname: name });
680	  } else if (op === "delete") {
681	    upid = await conn.del(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}`);
682	  } else {
683	    upid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/snapshot/${name}/rollback`, {});
684	  }
685	  await conn.waitForTask(upid, 600_000);
686	  if (op === "rollback") {
687	    // rollback leaves the VM stopped; bring it back if the server should be running
688	    const current = await db.server.findUnique({ where: { id: server.id } });
689	    if (current?.status === "RUNNING") {
690	      try {
691	        const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${server.vmid}/status/start`, {});
692	        await conn.waitForTask(startUpid);
693	      } catch { /* may already be running */ }
694	    }
695	  }
696	}
