774	/**
775	 * Create one backup and PROVE it exists before saying so.
776	 *
777	 * INCIDENT H4 (2026-07-26 rehearsal): this handler gated only the vzdump task's
778	 * exit status — it never checked that an archive was written, had no failure
779	 * notification, and `Server.lastAutoBackup` was stamped by the SWEEP at enqueue
780	 * time. A customer could read "Last automatic backup: today" every night for a
781	 * month with nothing in storage, and find out at restore time.
782	 *
783	 * Now: snapshot the archive list before the run, re-read it after, and require a
784	 * volid that was not there and is not empty (`freshBackupProof`). Only that
785	 * writes `lastAutoBackup`. A failure notifies the customer with the reason and a
786	 * command, rather than leaving a stale-but-cheerful timestamp behind.
787	 */
788	async function backupCreate(job: Job) {
789	  const server = await loadServer(job);
790	  if (SANDBOX) {
791	    await sandboxAnimateJob(job.id, [
792	      { pct: 5, step: "Starting" },
793	      { pct: 25, step: "Creating archive… 25%" },
794	      { pct: 55, step: "Creating archive… 55%" },
795	      { pct: 80, step: "Creating archive… 80%" },
796	      { pct: 95, step: "Finalizing" },
797	      { pct: 100, step: "Backup complete" },
798	    ]);
799	    // Deliberately NOT stamping lastAutoBackup here: no archive exists, and the
800	    // column means "a backup was observed in storage".
801	    await notify(
802	      server.userId,
803	      `Backup simulated (sandbox) for ${server.hostname}`,
804	      "Sandbox only — no VM was contacted and no archive was written. This is not a restore point.",
805	      `/dashboard/servers/${server.id}`
806	    );
807	    return;
808	  }
809	  if (server.vmid == null) {
810	    throw new Error("backup: this server has no VMID yet, so there is nothing to back up.");
811	  }
812	  const vmid = server.vmid;
813	
814	  try {
815	    await reportJobProgress(job.id, 2, "Starting");
816	    const { conn } = await nodeFor(server);
817	
818	    // Snapshot what already exists. Membership of this set — not a timestamp
819	    // comparison — is what makes "a new archive appeared" unarguable: ctime comes
820	    // off the hypervisor and our window would come off the worker's clock.
821	    const before = await listBackupsOn(conn, vmid);
822	
823	    const upid = await conn.post(`/nodes/${conn.node}/vzdump`, {
824	      vmid,
825	      storage: "backup",
826	      mode: "snapshot",
827	      compress: "zstd",
828	    });
829	    await waitForTaskProgress(
830	      conn,
831	      upid,
832	      (progress, step) => reportJobProgress(job.id, progress, step),
833	      { timeoutMs: 3_600_000, phase: "backup" }
834	    );
835	
836	    await reportJobProgress(job.id, 96, "Verifying archive");
837	    const after = await listBackupsOn(conn, vmid);
838	    const proof = freshBackupProof({ vmid, before, after });
839	    if (!proof.proven) throw new Error(`backup not verified — ${proof.reason}`);
840	
841	    await reportJobProgress(job.id, 100, "Backup complete");
842	
843	    // Retention: keep only the latest few backups for this server; prune the rest.
844	    try {
845	      const pruned = await pruneBackups(conn, vmid, CUSTOMER_BACKUP_KEEP);
846	      if (pruned > 0) console.log(`[backup] pruned ${pruned} old backup(s) for vmid ${vmid} (keep ${CUSTOMER_BACKUP_KEEP})`);
847	    } catch (e) {
848	      console.error(`[backup] prune failed for vmid ${vmid}`, e);
849	    }
850	
851	    // The ONLY writer of lastAutoBackup, and only on proof.
852	    await db.server.update({ where: { id: server.id }, data: { lastAutoBackup: new Date() } });
853	
854	    await notify(
855	      server.userId,
856	      `Backup completed for ${server.hostname}`,
857	      `Verified present in backup storage: ${proof.volid} (${humanBytes(proof.sizeBytes)}).`,
858	      `/dashboard/servers/${server.id}`
859	    );
860	  } catch (e: any) {
861	    // Tell the customer it broke. Only on the final attempt, so the worker's
862	    // three retries do not produce three notifications for one bad night.
863	    if (job.attempts >= MAX_ATTEMPTS) {
864	      await notify(
865	        server.userId,
866	        `Backup FAILED for ${server.hostname}`,
867	        `${String(e?.message ?? e).slice(0, 400)} — this server has no new restore point. ` +
868	          `Your last verified backup (if any) is shown under Backups.`,
869	        `/dashboard/servers/${server.id}`
870	      );
871	    }
872	    throw e;
873	  }
874	}
