68	export async function backupRestore(job: Job): Promise<void> {
69	  const server = await loadServer(job.serverId!);
70	  if (SANDBOX) {
71	    // Simulate a successful restore — animate the bar 0→100 so staging shows it.
72	    const steps = [
73	      { pct: 8, step: "Stopping server" },
74	      { pct: 30, step: "Restoring archive… 25%" },
75	      { pct: 55, step: "Restoring archive… 55%" },
76	      { pct: 80, step: "Restoring archive… 85%" },
77	      { pct: 95, step: "Starting server" },
78	      { pct: 100, step: "Restore complete" },
79	    ];
80	    for (const s of steps) {
81	      await reportJobProgress(job.id, s.pct, s.step);
82	      await new Promise((r) => setTimeout(r, 500));
83	    }
84	    await notify(
85	      server.userId,
86	      `Backup restored on ${server.hostname}`,
87	      "Your server was restored from the selected backup (sandbox).",
88	      `/dashboard/servers/${server.id}`
89	    );
90	    return;
91	  }
92	  if (!server.vmid) throw new Error("restore: server has no VM");
93	
94	  const payload = (job.payload ?? {}) as { volid?: string };
95	  const volid = payload.volid;
96	  if (!volid) throw new Error("restore: missing volid");
97	
98	  // DATA SAFETY (critical): step 2 below runs `qmrestore --force` over the live
99	  // vmid. PVE calls destroy_vm first ("avoid zombie disks when restoring over an
100	  // existing VM"), and destroy_vm frees EVERY volume that vmid owns — including
101	  // detached `unusedN` entries, because it passes include_unused => 1. Restoring
102	  // an archive taken before a volume was attached would therefore wipe that
103	  // volume's data while the Volume row still bills for it.
104	  //
105	  // Matches the reinstall guard, and mirrors requestRestore()'s check so a job
106	  // queued before that check existed (or enqueued by any other path) still cannot
107	  // destroy data. Counting by serverId alone is deliberate — detaching keeps the
108	  // disk owned by this vmid, so DETACHED volumes are just as exposed as attached.
109	  const pinnedVolumes = await db.volume.findMany({ where: { serverId: server.id } });
110	  const realPinned = pinnedVolumes.filter(
111	    (v) => !(typeof v.diskName === "string" && v.diskName.startsWith("sandbox:"))
112	  );
113	  if (realPinned.length > 0) {
114	    const names = realPinned.map((v) => `"${v.name}"`).join(", ");
115	    throw new Error(
116	      `Restore blocked to protect your data volume(s): ${names}. Restoring replaces every ` +
117	        `disk this server owns, which would destroy them permanently. Move or delete them first.`
118	    );
119	  }
120	
121	  const conn = await nodeFor(server);
122	  const vmid = server.vmid;
123	  const wasRunning = server.status === "RUNNING";
124	
125	  // 1) Stop the VM so the disk can be overwritten (ignore "already stopped").
126	  await reportJobProgress(job.id, 3, "Stopping server");
127	  try {
128	    const stopUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/stop`, {});
129	    await conn.waitForTask(stopUpid);
130	  } catch {
131	    /* already stopped / not running */
132	  }
133	  await db.server.update({ where: { id: server.id }, data: { status: "STOPPED" } });
134	
135	  // 2) Restore the archive over the existing VMID (force overwrite). Storage is
136	  //    left to the archive's recorded config so disks land where they were.
137	  //    Task progress (0..100) is mapped into the 10..90 window of the bar.
138	  await reportJobProgress(job.id, 10, "Restoring archive…");
139	  const restoreUpid = await conn.post(`/nodes/${conn.node}/qemu`, {
140	    vmid,
141	    archive: volid,
142	    force: 1,
143	  });
144	  await waitForTaskProgress(
145	    conn,
146	    restoreUpid,
147	    (progress, step) => reportJobProgress(job.id, progress, step),
148	    { timeoutMs: 3_600_000, phase: "restore", base: 10, span: 80 }
149	  );
150	
151	  // 3) Bring the VM back up if it was running before the restore.
152	  if (wasRunning) {
153	    await reportJobProgress(job.id, 95, "Starting server");
154	    const startUpid = await conn.post(`/nodes/${conn.node}/qemu/${vmid}/status/start`, {});
155	    await conn.waitForTask(startUpid);
156	    await db.server.update({ where: { id: server.id }, data: { status: "RUNNING" } });
157	  }
158	  await reportJobProgress(job.id, 100, "Restore complete");
159	
160	  await notify(
161	    server.userId,
162	    `Backup restored on ${server.hostname}`,
163	    "Your server was restored from the selected backup. Any changes made after that backup are gone.",
164	    `/dashboard/servers/${server.id}`
165	  );
166	}
