915	/**
916	 * Refund a per-server disk expansion that was paid for but never delivered.
917	 *
918	 * The DISK_EXPAND handler advances `Server.extraDiskGB` only AFTER the disk has
919	 * really grown, so that field is the ground truth for "did the customer get what
920	 * they paid for". We refund only when it never reached the job's target — which
921	 * also keeps this safe against the partial-success case (disk grown, filesystem
922	 * left for the customer to grow by hand): that path completes successfully, sets
923	 * extraDiskGB, and is therefore never refunded.
924	 *
925	 * Idempotent per job via the reconcile audit marker.
926	 */
927	async function reconcileFailedDiskExpand(job: Job) {
928	  const p = (job.payload ?? {}) as { prorateCents?: number; addGB?: number; targetExtraDiskGB?: number };
929	  const cents = p.prorateCents ?? 0;
930	  if (cents <= 0 || !job.serverId) return;
931	
932	  const already = await db.auditLog.findFirst({
933	    where: { action: "server.disk_expand.reconcile", detail: { contains: `job=${job.id}` } },
934	  });
935	  if (already) return;
936	
937	  const server = await db.server.findUnique({
938	    where: { id: job.serverId },
939	    select: { userId: true, hostname: true, extraDiskGB: true },
940	  });
941	  if (!server) return;
942	
943	  // The expansion actually landed (or a later one superseded it) — the customer
944	  // has the storage, so the charge stands. Nothing to unwind.
945	  const target = Number(p.targetExtraDiskGB ?? 0);
946	  if (target > 0 && server.extraDiskGB >= target) return;
947	
948	  try {
949	    await db.$transaction([
950	      db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
951	      db.walletTransaction.create({
952	        data: {
953	          userId: server.userId,
954	          amountCents: cents,
955	          description: `Refund: failed storage expansion (+${p.addGB ?? "?"} GB) — ${server.hostname}`,
956	        },
957	      }),
958	      db.notification.create({
959	        data: {
960	          userId: server.userId,
961	          title: `Storage expansion failed on ${server.hostname} — refunded`,
962	          body: `We couldn't add the storage, so $${(cents / 100).toFixed(2)} has been credited back to your wallet. Your server and its data are untouched.`,
963	          href: `/dashboard/servers/${job.serverId}`,
964	        },
965	      }),
966	    ]);
967	    await db.auditLog.create({
968	      data: {
969	        userId: server.userId,
970	        action: "server.disk_expand.reconcile",
971	        detail: `job=${job.id} addGB=${p.addGB} cents=${cents}`,
972	      },
973	    });
974	  } catch (e: any) {
975	    await db.auditLog
976	      .create({
977	        data: {
978	          userId: server.userId,
979	          action: "server.disk_expand.reconcile.uncharged",
980	          detail: `job=${job.id} cents=${cents} :: ${e?.message ?? e}`,
981	        },
982	      })
983	      .catch(() => {});
984	  }
985	}
