987	/**
988	 * Reverse a money side-effect that a job committed up-front but never delivered.
989	 * Server actions charge/credit the wallet before enqueuing the worker job (so the
990	 * UI reflects the change immediately); if the job then fails terminally the money
991	 * must be unwound or the customer is charged for a resize that never happened
992	 * (up) or keeps a downgrade credit for hardware they still have (down).
993	 * Idempotent per job: guarded by the RECONCILED audit marker so a re-run can't
994	 * double-reverse.
995	 */
996	async function reconcileFailedJob(job: Job) {
997	  if (job.type === "DISK_EXPAND") return reconcileFailedDiskExpand(job);
998	  if (job.type !== "RESIZE") return;
999	  const p = (job.payload ?? {}) as { prorateCents?: number; direction?: "up" | "down" };
1000	  const cents = p.prorateCents ?? 0;
1001	  if (cents <= 0 || !job.serverId) return;
1002	
1003	  // Idempotency: skip if we already reversed this exact job.
1004	  const already = await db.auditLog.findFirst({
1005	    where: { action: "server.resize.reconcile", detail: { contains: `job=${job.id}` } },
1006	  });
1007	  if (already) return;
1008	
1009	  const server = await db.server.findUnique({ where: { id: job.serverId }, select: { userId: true, hostname: true } });
1010	  if (!server) return;
1011	
1012	  try {
1013	    if (p.direction === "up") {
1014	      // Upgrade charge never delivered → refund the prorated charge.
1015	      await db.$transaction([
1016	        db.user.update({ where: { id: server.userId }, data: { balanceCents: { increment: cents } } }),
1017	        db.walletTransaction.create({
1018	          data: { userId: server.userId, amountCents: cents, description: `Refund: failed upgrade — ${server.hostname}` },
1019	        }),
1020	      ]);
1021	    } else if (p.direction === "down") {
1022	      // Downgrade credit was given but hardware unchanged → claw the credit back.
1023	      // Guarded so it can never drive the balance negative; if the customer already
1024	      // spent it, we log and leave it (best-effort — they keep a small windfall).
1025	      await db.$transaction(async (tx) => {
1026	        await debitWallet(tx, server.userId, cents);
1027	        await tx.walletTransaction.create({
1028	          data: { userId: server.userId, amountCents: -cents, description: `Reversed downgrade credit (resize failed) — ${server.hostname}` },
1029	        });
1030	      });
1031	    }
1032	    await db.auditLog.create({
1033	      data: { userId: server.userId, action: "server.resize.reconcile", detail: `job=${job.id} dir=${p.direction} cents=${cents}` },
1034	    });
1035	  } catch (e: any) {
1036	    // InsufficientBalanceError on a down-reversal is expected/acceptable; record it.
1037	    await db.auditLog.create({
1038	      data: { userId: server.userId, action: "server.resize.reconcile.uncharged", detail: `job=${job.id} dir=${p.direction} cents=${cents} :: ${e?.message ?? e}` },
1039	    }).catch(() => {});
1040	  }
1041	}
