1043	async function runJob(job: Job) {
1044	  // The job is already atomically claimed (status RUNNING, attempts incremented)
1045	  // by the loop's compare-and-swap before we get here — see the CAS in main().
1046	  console.log(`[worker] job ${job.id} ${job.type} server=${job.serverId}`);
1047	  try {
1048	    await handlers[job.type](job);
1049	    await db.job.update({ where: { id: job.id }, data: { status: "DONE" } });
1050	    console.log(`[worker] job ${job.id} DONE`);
1051	  } catch (e: any) {
1052	    let error = `${e?.message ?? e}${e?.body ? ` :: ${e.body}` : ""}`;
1053	    // Defense in depth: a child process (e.g. `sshpass -p <rootPassword> …`) can
1054	    // leak the server's root password into the thrown message. Redact it before
1055	    // it is persisted to Job.error. Redact BEFORE slicing so a truncation can't
1056	    // sever the match. Best-effort — never let redaction lookup fail the job path.
1057	    if (job.serverId) {
1058	      try {
1059	        const s = await db.server.findUnique({
1060	          where: { id: job.serverId },
1061	          select: { rootPassword: true, rootPasswordEnc: true },
1062	        });
1063	        const pw = s ? serverRootPassword(s) : null;
1064	        if (pw) error = error.split(pw).join("***");
1065	      } catch {
1066	        /* best-effort redaction */
1067	      }
1068	    }
1069	    error = error.slice(0, 2000);
1070	    console.error(`[worker] job ${job.id} FAILED: ${error}`);
1071	    const current = await db.job.findUnique({ where: { id: job.id } });
1072	    const retriable = (current?.attempts ?? MAX_ATTEMPTS) < MAX_ATTEMPTS;
1073	    await db.job.update({
1074	      where: { id: job.id },
1075	      data: { status: retriable ? "QUEUED" : "FAILED", error },
1076	    });
1077	    if (!retriable) {
1078	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
1079	      if (job.serverId) {
1080	        const stillExists = await db.server.findUnique({ where: { id: job.serverId } });
1081	        if (stillExists) {
1082	          // Only jobs that actually change the VM's run/disk state should strand the
1083	          // server in ERROR. Side operations — backup, snapshot-create, the control-
1084	          // panel db/website/app/cron/service ops, SSL, migrate copy, game update —
1085	          // never touch the VM's run state; their failures surface via the executor's
1086	          // own notification and must NOT flip the whole server to ERROR (a failed
1087	          // backup was wrongly making the server look like it had shut down).
1088	          if (VM_STATE_FAILURE_JOBS.has(job.type)) {
1089	            await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
1090	          }
1091	          // A terminally-failed PROVISION must not leak its allocated dedicated IP:
1092	          // release it back to the pool (deletes the billable OVH Virtual MAC) and
1093	          // clear the (UNIQUE) ipAddress so the next server can claim it.
1094	          if (job.type === "PROVISION" && !SANDBOX) {
1095	            await releaseDedicatedIp(job.serverId).catch((err) =>
1096	              console.error(`[worker] release dedicated IP on failed provision ${job.id}`, err)
1097	            );
1098	            await db.server
1099	              .update({ where: { id: job.serverId }, data: { ipAddress: null } })
1100	              .catch(() => {});
1101	          }
1102	        }
1103	      }
1104	    }
1105	  }
1106	}
