1108	/**
1109	 * Recover jobs left RUNNING by a previous worker crash/restart. Without this a
1110	 * killed worker leaves a job RUNNING forever, which permanently blocks the
1111	 * server's "one in-flight job" guard and strands it in a transitional state.
1112	 */
1113	async function reapStuckJobs() {
1114	  const stuck = await db.job.findMany({ where: { status: "RUNNING" } });
1115	  for (const job of stuck) {
1116	    const retriable = job.attempts < MAX_ATTEMPTS;
1117	    await db.job.update({
1118	      where: { id: job.id },
1119	      data: { status: retriable ? "QUEUED" : "FAILED", error: retriable ? null : "Worker restarted mid-job" },
1120	    });
1121	    if (!retriable) {
1122	      await reconcileFailedJob(job).catch((err) => console.error(`[worker] reconcile ${job.id} failed`, err));
1123	      if (job.serverId) {
1124	        const s = await db.server.findUnique({ where: { id: job.serverId } });
1125	        if (s && ["PROVISIONING", "REINSTALLING", "DELETING"].includes(s.status)) {
1126	          await db.server.update({ where: { id: job.serverId }, data: { status: "ERROR" } });
1127	        }
1128	      }
1129	    }
1130	    console.log(`[worker] reaped stuck job ${job.id} (${job.type}) -> ${retriable ? "QUEUED" : "FAILED"}`);
1131	  }
1132	}
