98	  if (!n) {
99	    return {
100	      conn: {
101	        get: pve.get,
102	        post: pve.post,
103	        put: pve.put,
104	        del: pve.del,
105	        node: envNode,
106	        waitForTask,
107	        nextVmid,
108	        vmStatus,
109	      } as any,
110	      row: null,
111	    };
112	  }
113	  return {
114	    conn: pveFor({ apiUrl: n.apiUrl, pveNode: n.pveNode, tokenId: n.tokenId, tokenSecret: n.tokenSecret }),
115	    row: n,
