127	/** Strip Proxmox disk options: "vmdata:vm-101-disk-1,size=10G" -> "vmdata:vm-101-disk-1". */
128	function volidOf(configValue: unknown): string {
129	  return String(configValue ?? "").split(",")[0].trim();
130	}
131	
132	/**
133	 * True for a real Proxmox disk volid such as "vmdata:vm-102-disk-1" (or a
134	 * file/dir volid like "vmdata:102/vm-102-disk-1.raw"). Used to reject empty/
135	 * garbage read-backs so `Volume.diskName` is never persisted as a non-volid.
136	 */
137	function isRealVolid(v: unknown): v is string {
138	  return typeof v === "string" && /^[^,\s:]+:\S*vm-\d+-disk-\d+/.test(v.trim());
139	}
140	
141	/** The vmid that OWNS a volid ("vmdata:vm-102-disk-1" -> 102), or null. */
142	function vmidOfVolid(volid: unknown): number | null {
143	  const m = /vm-(\d+)-disk-\d+/.exec(String(volid ?? ""));
144	  if (!m) return null;
145	  const n = Number(m[1]);
146	  return Number.isInteger(n) && n > 0 ? n : null;
147	}
148	
149	/** All disk volids currently referenced by a VM config (scsi/virtio/ide/sata/unused). */
150	function diskVolids(config: Record<string, any>): string[] {
151	  const out: string[] = [];
152	  for (const [k, v] of Object.entries(config)) {
153	    if (typeof v !== "string") continue;
154	    if (!/^(scsi|virtio|ide|sata|unused)\d+$/.test(k)) continue;
155	    const id = volidOf(v);
156	    if (isRealVolid(id)) out.push(id);
157	  }
158	  return out;
159	}
160	
161	/** First free scsiN slot (scsi0 is the OS disk). Proxmox supports scsi0..scsi30. */
162	function freeScsiSlot(config: Record<string, any>): string {
163	  for (let i = 1; i <= 30; i++) {
164	    if (config[`scsi${i}`] === undefined) return `scsi${i}`;
165	  }
166	  throw new Error("no free scsi slot available on this VM");
167	}
168	
169	/** Find the config key (scsiN / unusedN / …) that currently references `volid`. */
170	function keyForVolid(config: Record<string, any>, volid: string): string | null {
171	  for (const [k, v] of Object.entries(config)) {
172	    if (typeof v === "string" && volidOf(v) === volid) return k;
173	  }
174	  return null;
175	}
