177	/**
178	 * Read a VM config, polling until `ready(config)` is satisfied.
179	 *
180	 * Proxmox applies a config POST ASYNCHRONOUSLY: the call returns before the
181	 * config file is rewritten, so an immediate GET can still return the pre-write
182	 * view. Every read-after-write here uses this — the un-polled version is how
183	 * ATTACHED volumes ended up with `diskName === null`, which then made a
184	 * re-attach hand back a brand-new empty disk and orphan the real one.
185	 */
186	async function waitForConfig(
187	  conn: any,
188	  vmid: number,
189	  ready: (config: Record<string, any>) => boolean,
190	  tries = 10,
191	  delayMs = 1000
192	): Promise<Record<string, any>> {
193	  let config = (await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`)) as Record<string, any>;
194	  for (let i = 0; i < tries && !ready(config); i++) {
195	    await new Promise((r) => setTimeout(r, delayMs));
196	    config = (await conn.get(`/nodes/${conn.node}/qemu/${vmid}/config`)) as Record<string, any>;
197	  }
198	  return config;
199	}
