221	// ===========================================================================
222	// GUEST SIDE — detect / format / mount / unmount
223	// ===========================================================================
224	/**
225	 * Everything below runs inside the customer's VM over SSH, and every command is
226	 * built the way lib/ssh-exec.ts demands: values are validated against a
227	 * shell-inert allowlist FIRST (we reject, never sanitize) and quoted second.
228	 *
229	 * The formatting decision is the most dangerous operation in this file, so it is
230	 * deliberately gated by five INDEPENDENT layers, and any one of them failing (or
231	 * being merely unclear) means we mount nothing and format nothing:
232	 *
233	 *   1. IDENTITY — the device must be one that appeared in the guest between a
234	 *      snapshot taken BEFORE the hot-plug and a poll taken after it, and exactly
235	 *      one such device may appear. We never guess "probably /dev/sdb".
236	 *   2. SIZE — that device's size must match the volume's nominal size.
237	 *   3. HISTORY — the Volume row must never have carried a filesystem
238	 *      (`fsType`/`mountPath`/`inUse` all unset). If the row says it was
239	 *      formatted but the disk looks blank, that contradiction means we may be
240	 *      looking at the wrong device: refuse and report, touch nothing.
241	 *   4. SIGNATURES — `blkid`, `wipefs -n`, children, holders and mountpoints must
242	 *      all come back empty, AND three separate 1–4 MiB windows (start, middle,
243	 *      end) must read as pure zeros. Every filesystem/partition table/LVM/LUKS/
244	 *      md-raid layout writes a header inside those windows, so "no signature and
245	 *      zeros at both ends" is as close to proof-of-blank as a disk allows.
246	 *   5. mke2fs ITSELF — `mkfs.ext4` is invoked with a SINGLE `-F`. That waives
247	 *      only the "this is a whole device, not a partition" objection; a single
248	 *      `-F` still makes mke2fs refuse a device that is mounted or otherwise in
249	 *      use by the kernel (two are required to override that), so the kernel gets
250	 *      the last veto after all our own checks.
251	 */
252	
253	const GiB = 1024 ** 3;
254	/** A bare kernel block-device name we are willing to interpolate: "sdb", "vdc". */
255	const DEV_NAME_RE = /^[a-z][a-z0-9]{1,31}$/;
256	const UUID_RE = /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}$/;
257	/** Absolute mount path we either generate or read back from the guest. */
258	const MOUNT_PATH_RE = /^\/[A-Za-z0-9._/-]{1,120}$/;
259	/** Filesystems we are willing to mount unattended. */
260	const MOUNTABLE_FS = new Set(["ext2", "ext3", "ext4", "xfs", "btrfs"]);
261	/** What a blank volume gets formatted with. */
262	const VOLUME_FS = "ext4";
263	
264	/** Strip control characters and clamp — everything read back from the guest. */
265	function clean(s: unknown, max: number): string {
266	  return String(s ?? "")
267	    .replace(/[\x00-\x1f\x7f]/g, " ")
268	    .trim()
269	    .slice(0, max);
270	}

