961	/**
962	 * VOLUME_ATTACH — attach the volume to the target server's VM at a free scsi
963	 * slot, then make it actually usable inside the guest.
964	 *
965	 * Three cases:
966	 *   • first attach            → Proxmox creates "<storage>:<sizeGB>"
967	 *   • re-attach, same server  → re-use the existing volid, data preserved
968	 *   • attach to another server → reassign the disk to that VM (data moves with it)
969	 */
970	export async function volumeAttach(job: Job): Promise<void> {
971	  const volume = await loadVolume(job);
972	  const target = await loadAttachTarget(job, volume);
973	
974	  if (SANDBOX) {
975	    // Simulate the whole thing — no Proxmox call, no SSH — but do record the
976	    // filesystem facts so safe-detach can be exercised in staging.
977	    await db.volume.update({
978	      where: { id: volume.id },
979	      data: {
980	        status: "ATTACHED",
981	        serverId: target?.id ?? volume.serverId ?? null,
982	        diskName: volume.diskName ?? `sandbox:vol-${volume.id}`,
983	        fsType: volume.fsType ?? VOLUME_FS,
984	        mountPath: volume.mountPath ?? defaultMountPath(volume.id),
985	        inUse: true,
986	      },
987	    });
988	    await notify(
989	      volume.userId,
990	      `Volume "${volume.name}" attached${target ? ` to ${target.hostname}` : ""}`,
991	      `${volume.sizeGB} GB is mounted at ${volume.mountPath ?? defaultMountPath(volume.id)} (sandbox — no real disk was touched).`,
992	      target ? `/dashboard/servers/${target.id}` : "/dashboard/volumes"
993	    );
994	    return;
995	  }
996	  if (!target || !target.vmid) throw new Error("volume attach: server has no VM");
997	
998	  const { conn, row } = await nodeFor(target);
999	  const storage = row?.storageNvme ?? "vmdata";
1000	
1001	  // Snapshot the guest's disks BEFORE the hot-plug: the set difference afterwards
1002	  // is the only trustworthy way to know which /dev/sdX is this volume, and it is
1003	  // what stands between a format and somebody else's data.
1004	  const targetRun = await vmRunState(conn, target.vmid);
1005	  let guestBefore: Set<string> | null = null;
1006	  if (targetRun === "running" || (targetRun === "unknown" && target.status === "RUNNING")) {
1007	    try {
1008	      guestBefore = await withServerSsh(target, (c) => guestDiskNames(c));
1009	    } catch {
1010	      guestBefore = null; // unreachable guest: attach anyway, prepare nothing
1011	    }
1012	  }
1013	
1014	  const hadDisk = isRealVolid(volume.diskName);
1015	  const sourceVmid = hadDisk ? vmidOfVolid(volume.diskName) : null;
1016	  let slot: string;
1017	  let volid: string | null = null;
1018	
1019	  if (sourceVmid && sourceVmid !== target.vmid) {
1020	    // ── Portability: the disk lives on another VM; move it. ────────────────
1021	    const sourceServer = volume.serverId
1022	      ? await db.server.findUnique({ where: { id: volume.serverId }, include: { node: true } })
1023	      : await db.server.findFirst({ where: { vmid: sourceVmid }, include: { node: true } });
1024	    const sourceNode = (await nodeFor(sourceServer)).row?.pveNode ?? envNode;
1025	    if (sourceNode !== conn.node) {
1026	      throw new Error(
1027	        `volume "${volume.name}" holds data on Proxmox node ${sourceNode} and ${target.hostname} is on ${conn.node}. ` +
1028	          `Moving a disk between nodes is not supported — attach it to a server on ${sourceNode}.`
1029	      );
1030	    }
1031	    const moved = await reassignDiskToServer(
1032	      conn,
1033	      volume,
1034	      sourceVmid,
1035	      (sourceServer?.status ?? "RUNNING") === "RUNNING",
1036	      { vmid: target.vmid, hostname: target.hostname }
1037	    );
1038	    slot = moved.slot;
1039	    volid = moved.volid;
1040	  } else {
1041	    // ── First attach, or a re-attach to the same server. ───────────────────
1042	    const config = (await conn.get(`/nodes/${conn.node}/qemu/${target.vmid}/config`)) as Record<string, any>;
1043	    slot = freeScsiSlot(config);
1044	    // Snapshot the disks the VM already owns so we can identify a freshly-created
1045	    // one by diff if the slot read-back is unusable (see fallback below).
1046	    const before = new Set(diskVolids(config));
1047	
1048	    // A volume that has ever carried a filesystem MUST NOT be re-created from
1049	    // scratch: that hands back an empty disk and orphans the customer's data with
1050	    // no DB reference left pointing at it.
1051	    if (!hadDisk && (volume.fsType || volume.mountPath || volume.inUse)) {
1052	      throw new Error(
1053	        `volume "${volume.name}" is recorded as ${volume.fsType ?? "formatted"} but has no disk id on record. ` +
1054	          `Refusing to create a new empty disk — the existing one must be found first.`
1055	      );
1056	    }
1057	
1058	    // Re-use the existing disk (by volid) if this volume was attached before;
1059	    // otherwise let Proxmox create a fresh <storage>:<sizeGB> disk.
1060	    const source = volume.diskName ? volume.diskName : `${storage}:${volume.sizeGB}`;
1061	    await conn.post(`/nodes/${conn.node}/qemu/${target.vmid}/config`, { [slot]: source });
1062	
1063	    // Record the STABLE volid (vmdata:vm-<vmid>-disk-N) so detach/re-attach and the
1064	    // reinstall data-safety guard can find this disk later. This MUST NOT be left
1065	    // null: derive it with layered fallbacks rather than trusting a single read.
1066	    const after = await waitForConfig(conn, target.vmid, (c) => isRealVolid(volidOf(c[slot])));
1067	    // 1) Preferred: the volid Proxmox kept/created at the slot we just wrote.
1068	    const atSlot = volidOf(after[slot]);
1069	    if (isRealVolid(atSlot)) {
1070	      volid = atSlot;
1071	    } else if (volume.diskName && isRealVolid(volume.diskName)) {
1072	      // 2) Re-attach path: the disk we asked to attach is a known-good volid.
1073	      volid = volume.diskName;
1074	    } else {
1075	      // 3) First-attach path where the slot read-back didn't yield a volid (pending
1076	      //    config view, momentary omission, …): identify the disk that newly appeared.
1077	      const appeared = diskVolids(after).filter((v) => !before.has(v));
1078	      if (appeared.length === 1) volid = appeared[0];
1079	    }
1080	  }
1081	
1082	  // ── Guest side: format (only if provably blank) and mount. ───────────────
1083	  let prep: PrepareResult;
1084	  if (guestBefore) {
1085	    prep = await prepareGuestVolume(target, volume, guestBefore);
1086	  } else if (targetRun === "stopped") {
1087	    prep = { prepared: false, detail: "the server is not running, so the disk could not be mounted yet" };
1088	  } else {
1089	    prep = { prepared: false, detail: "the server could not be reached over SSH, so the disk was not formatted or mounted" };
1090	  }
1091	
1092	  await db.volume.update({
1093	    where: { id: volume.id },
1094	    data: {
1095	      status: "ATTACHED",
1096	      serverId: target.id,
1097	      // Never regress a previously-recorded good volid to null on a retry.
1098	      diskName: volid ?? volume.diskName ?? null,
1099	      // Only claim a filesystem/mount when we actually established one; never
1100	      // wipe a known fsType because one attempt could not reach the guest.
1101	      fsType: prep.prepared ? prep.fsType : prep.fsType ?? volume.fsType,
1102	      mountPath: prep.prepared ? prep.mountPath : volume.mountPath,
1103	      inUse: prep.prepared,
1104	    },
1105	  });
1106	
1107	  if (prep.prepared) {
1108	    await notify(
1109	      volume.userId,
1110	      `Volume "${volume.name}" is mounted on ${target.hostname}`,
1111	      `${volume.sizeGB} GB attached as ${slot} — ${prep.detail}. Detaching it will unmount it first, and while it is assigned to ${target.hostname} that server cannot be reinstalled or restored from a backup.`,
1112	      `/dashboard/servers/${target.id}`
1113	    );
1114	  } else {
1115	    await notify(
1116	      volume.userId,
1117	      `Volume "${volume.name}" attached to ${target.hostname} — not mounted`,
1118	      `${volume.sizeGB} GB is attached as ${slot}, but ${prep.detail}. No data was written to the disk. To finish by hand:\n${manualPrepareHint(volume.id)}`,
1119	      `/dashboard/servers/${target.id}`
1120	    );
1121	  }
1122	}
1123	
1124	/**
1125	 * VOLUME_DETACH — unmount the filesystem, then unplug the disk from the VM
1126	 * (Proxmox moves it to an "unused" entry, preserving the data).
1127	 *
1128	 * ─── WHY THE VOLUME STAYS PINNED TO THE SERVER ──────────────────────────────
1129	 * `Volume.serverId` is NOT cleared while a real disk is still owned by that vmid.
1130	 * A detached disk lives on as an `unusedN` entry belonging to `vm-<vmid>-disk-N`,
1131	 * and PVE's `destroy_vm` frees those too (`include_unused => 1`), so a reinstall
1132	 * or a `qmrestore --force` on that vmid destroys it. The reinstall/restore guards
1133	 * in lib/actions.ts, worker/index.ts, lib/actions-server-ops.ts and
1134	 * worker/restore.ts count volumes by `serverId` ALONE for exactly that reason —
1135	 * clearing the pin here would blind them and reopen the "detach, then reinstall,
1136	 * data gone" path.
1137	 *
1138	 * The pin IS cleared when nothing physical is left behind (no disk was ever
1139	 * created), and it is MOVED to the new server by VOLUME_ATTACH once the disk has
1140	 * really been reassigned — which is how a volume becomes portable without ever
1141	 * leaving a real disk unguarded.
1142	 */
1143	export async function volumeDetach(job: Job): Promise<void> {
1144	  const volume = await loadVolume(job);
1145	  const server = volume.server;
1146	  const payload = (job.payload ?? {}) as { ackInUse?: boolean };
1147	  const ackInUse = payload.ackInUse === true;
1148	  // Nothing physical to protect ⇒ safe to unpin. A real disk keeps its pin.
1149	  const keepsDisk = isRealVolid(volume.diskName);
1150	
1151	  if (SANDBOX) {
1152	    await db.volume.update({
1153	      where: { id: volume.id },
1154	      data: { status: "DETACHED", inUse: false, serverId: keepsDisk ? volume.serverId : null },
1155	    });
1156	    if (server) {
1157	      await notify(
1158	        volume.userId,
1159	        `Volume "${volume.name}" detached from ${server.hostname}`,
1160	        "The volume and its data are preserved and can be re-attached (sandbox).",
1161	        "/dashboard/volumes"
1162	      );
1163	    }
1164	    return;
1165	  }
1166	
1167	  // ── 1. Take the filesystem out of service first. ─────────────────────────
1168	  //
1169	  // A STOPPED VM has no live writers, so the config edit is safe on its own and
1170	  // no guest work is possible anyway. A RUNNING VM must be unmounted first. And
1171	  // when Proxmox will not tell us which it is, a volume we know carries a mounted
1172	  // filesystem is NOT unplugged on a guess.
1173	  const { conn: runConn } = server?.vmid ? await nodeFor(server) : { conn: null as any };
1174	  const run = server?.vmid && runConn ? await vmRunState(runConn, server.vmid) : "stopped";
