7	/**
8	 * Outbound-abuse detection. Compares each running server's cumulative outbound
9	 * byte counter (`Server.bwOutBytes`, written by the metering sweep in
10	 * worker/monitor.ts) against the previous sample to derive a sustained outbound
11	 * rate. A rate over the configurable threshold — a compromised VM sending spam,
12	 * DDoS egress, port scanning — raises an AbuseAlert and notifies admins.
13	 * Protects the platform's (and the mail IPs') reputation.
14	 *
15	 * This code existed before the metering sweep did, so `bwOutBytes` was always 0,
16	 * `deltaBytes` was always 0, and BANDWIDTH_SPIKE could never fire: the platform
17	 * shipped an abuse subsystem that could not detect anything. Now that it has a
18	 * real signal, the risk inverts — a false positive takes a paying customer's
19	 * server off the network. Everything below is therefore biased towards being
20	 * slow rather than wrong:
21	 *
22	 *   - The meter must be LIVE. Stale counters produce meaningless rates.
23	 *   - The window must be at least ABUSE_MIN_WINDOW_SEC, so what trips the alert
24	 *     is a sustained transfer and not a legitimate burst (a customer restoring a
25	 *     backup out of their VM can saturate a link for a minute).
26	 *   - A window the meter back-filled from RRD is skipped: back-filled bytes land
27	 *     in a single write but describe up to an hour of traffic, so the rate over
28	 *     that window is inflated by an accounting artefact, not by the customer.
29	 *   - A delta faster than any real link is discarded as a counter artefact.
30	 *   - AUTOMATIC SUSPENSION IS OFF BY DEFAULT and, even when enabled, needs the
31	 *     breach to repeat across consecutive windows. Alerting is the default
32	 *     response; a human decides.
33	 *
34	 * Settings: `abuse_outbound_mbps` (default 200), `abuse_autosuspend` (default
35	 * false — leave it false unless you have operators watching the queue).
36	 */
37	
38	/**
39	 * Minimum measurement window. The sweep runs ~every 10 min, so this is normally
40	 * satisfied comfortably; it only bites right after a worker restart, when the
41	 * first window can be short. A 60-second window at 200 Mbit/s is an ordinary
42	 * backup upload, not abuse.
43	 */
44	const ABUSE_MIN_WINDOW_SEC = 300;
45	
46	/**
47	 * Absolute egress floor for the window. Guards against an operator setting
48	 * `abuse_outbound_mbps` very low and turning ordinary traffic into alerts.
49	 */
50	const ABUSE_MIN_BYTES = 1_000_000_000; // 1 GB
51	
52	/** Consecutive breaching windows required before auto-suspend is even considered. */
53	const AUTOSUSPEND_MIN_BREACHES = 2;
54	/** …and the breaches must span at least this long in total. */
55	const AUTOSUSPEND_MIN_SUSTAIN_MS = 10 * 60_000;
56	/**
57	 * …and be contiguous: two breaches days apart are two incidents for a human to
58	 * read, not one sustained attack to act on automatically.
59	 */
60	const AUTOSUSPEND_MAX_BREACH_GAP_MS = 60 * 60_000;
61	
62	type SpikeMetric = {
63	  mbps: number;
64	  windowSec: number;
65	  bytes: number;
66	  breaches: number;
67	  firstBreachAt: string;
68	  lastBreachAt: string;
69	};
70	
71	function readMetric(raw: unknown): SpikeMetric | null {
72	  if (!raw || typeof raw !== "object") return null;
73	  const m = raw as Record<string, unknown>;
74	  const breaches = Number(m.breaches);
75	  if (!Number.isFinite(breaches)) return null;
76	  return {
77	    mbps: Number(m.mbps) || 0,
78	    windowSec: Number(m.windowSec) || 0,
79	    bytes: Number(m.bytes) || 0,
80	    breaches,
81	    firstBreachAt: typeof m.firstBreachAt === "string" ? m.firstBreachAt : "",
82	    lastBreachAt: typeof m.lastBreachAt === "string" ? m.lastBreachAt : "",
83	  };
84	}
