86	export async function abuseSweep(): Promise<void> {
87	  if (SANDBOX) return; // no real traffic to measure in the sandbox
88	
89	  // Without a live meter every delta below is either zero or stale, and a rate
90	  // computed from a stale counter is exactly the kind of number that suspends
91	  // the wrong customer. Sit out entirely rather than guess.
92	  const meter = await readBwMeterHealth();
93	  if (!meter.live) {
94	    if (meter.startedAt === null) {
95	      console.warn("[abuse] bandwidth metering has never run — outbound detection inactive");
96	    } else {
97	      console.warn(
98	        `[abuse] bandwidth metering is stale (last sample ${Math.round((meter.ageMs ?? 0) / 60_000)}m ago)` +
99	          " — skipping outbound detection this sweep"
100	      );
101	    }
102	    return;
103	  }
104	
105	  const thresholdMbps = await getSettingInt("abuse_outbound_mbps", 200);
106	  const autoSuspend = await getSettingBool("abuse_autosuspend", false);
107	  const now = new Date();
108	
109	  const servers = await db.server.findMany({
110	    where: { status: "RUNNING" },
111	    select: {
112	      id: true,
113	      userId: true,
114	      hostname: true,
115	      bwOutBytes: true,
116	      abuseBwMark: true,
117	      abuseBwMarkAt: true,
118	    },
119	  });
120	
121	  for (const s of servers) {
122	    const mark = s.abuseBwMark;
123	    const markAt = s.abuseBwMarkAt;
124	    // Re-mark for the next window regardless of outcome.
125	    await db.server.update({
126	      where: { id: s.id },
127	      data: { abuseBwMark: s.bwOutBytes, abuseBwMarkAt: now },
128	    });
129	
130	    if (mark == null || markAt == null) continue;
131	    const deltaBytes = Number(s.bwOutBytes - mark);
132	    const windowSec = (now.getTime() - markAt.getTime()) / 1000;
133	
134	    // Non-positive delta: either genuinely idle, or the metering period rolled
135	    // and reset the counter below the mark. Nothing to measure either way.
136	    if (deltaBytes <= 0) continue;
137	    // Too short to call anything "sustained".
138	    if (windowSec < ABUSE_MIN_WINDOW_SEC) continue;
139	    if (deltaBytes < ABUSE_MIN_BYTES) continue;
140	    // The meter back-filled inside this window, so these bytes cover more time
141	    // than the window does and the rate is inflated. Skip; the next clean window
142	    // will still catch a real abuser.
143	    if (meter.backfillAt && meter.backfillAt.getTime() >= markAt.getTime()) continue;
144	    // A delta faster than any physical link is a counter artefact. Never let one
145	    // suspend a customer.
146	    if (deltaBytes / windowSec > BW_MAX_PLAUSIBLE_BYTES_PER_SEC) {
147	      console.warn(
148	        `[abuse] discarding implausible outbound delta for ${s.hostname}: ` +
149	          `${deltaBytes} bytes over ${Math.round(windowSec)}s`
150	      );
151	      continue;
152	    }
153	
154	    const mbps = (deltaBytes * 8) / windowSec / 1_000_000;
155	    if (mbps < thresholdMbps) continue;
156	
157	    const severity = mbps >= thresholdMbps * 3 ? "HIGH" : "MEDIUM";
158	    const detailNow =
159	      `Sustained ~${mbps.toFixed(0)} Mbps outbound on ${s.hostname} over ` +
160	      `${Math.round(windowSec)}s (threshold ${thresholdMbps} Mbps, ` +
161	      `${(deltaBytes / 1e9).toFixed(1)} GB egress).`;
162	
163	    // One open alert per server+kind; don't spam the queue every sweep. The open
164	    // alert doubles as the breach counter that gates auto-suspend.
165	    const existing = await db.abuseAlert.findFirst({
166	      where: { serverId: s.id, kind: "BANDWIDTH_SPIKE", status: "OPEN" },
167	    });
168	
169	    let breaches = 1;
170	    let firstBreachAt = now;
171	    let lastBreachAt: Date | null = null;
172	
173	    if (existing) {
174	      const prev = readMetric(existing.metric);
175	      breaches = (prev?.breaches ?? 1) + 1;
176	      const prevFirst = prev?.firstBreachAt ? new Date(prev.firstBreachAt) : existing.createdAt;
177	      firstBreachAt = Number.isNaN(prevFirst.getTime()) ? existing.createdAt : prevFirst;
178	      const prevLast = prev?.lastBreachAt ? new Date(prev.lastBreachAt) : existing.createdAt;
179	      lastBreachAt = Number.isNaN(prevLast.getTime()) ? existing.createdAt : prevLast;
180	
181	      await db.abuseAlert.update({
182	        where: { id: existing.id },
183	        data: {
184	          // Escalate severity but never quietly de-escalate an alert a human may
185	          // already be reading.
186	          severity: severity === "HIGH" ? "HIGH" : existing.severity,
187	          detail: `${detailNow} Breach ${breaches} of an ongoing spike (first seen ${firstBreachAt.toISOString()}).`,
188	          metric: {
189	            mbps: Math.round(mbps),
190	            windowSec: Math.round(windowSec),
191	            bytes: deltaBytes,
192	            breaches,
193	            firstBreachAt: firstBreachAt.toISOString(),
194	            lastBreachAt: now.toISOString(),
195	          } satisfies SpikeMetric,
196	        },
197	      });
198	    } else {
199	      await db.abuseAlert.create({
200	        data: {
201	          serverId: s.id,
202	          userId: s.userId,
203	          kind: "BANDWIDTH_SPIKE",
204	          severity,
205	          detail: detailNow,
206	          metric: {
207	            mbps: Math.round(mbps),
208	            windowSec: Math.round(windowSec),
209	            bytes: deltaBytes,
210	            breaches: 1,
211	            firstBreachAt: now.toISOString(),
212	            lastBreachAt: now.toISOString(),
213	          } satisfies SpikeMetric,
214	        },
215	      });
216	    }
217	
218	    // notifyAdmins de-duplicates by title within a rolling window, so a spike
219	    // that persists for hours notifies once rather than every sweep.
220	    await notifyAdmins(
221	      `Abuse alert: outbound spike on ${s.hostname}`,
222	      `${s.hostname} is pushing ~${mbps.toFixed(0)} Mbps outbound over ${Math.round(windowSec)}s ` +
223	        `(threshold ${thresholdMbps} Mbps). Possible spam, DDoS egress, or port scanning. ` +
224	        `The server is still online — review and act in the admin abuse queue.`,
225	      "/admin/abuse"
226	    );
227	
228	    // ---- Automatic suspension: opt-in, and never on first detection ----------
229	    //
230	    // `abuse_autosuspend` defaults to false and should stay false unless someone
231	    // is watching the queue. Taking a paying customer offline by mistake is far
232	    // worse than reacting to abuse a sweep later, and legitimate traffic reaches
233	    // these rates: a big backup restored out of a VM, a launch-day game server,
234	    // a video site. Gates, all required:
235	    //   1. the operator explicitly enabled it,
236	    //   2. this window is >= 3x the threshold (HIGH),
237	    //   3. the breach repeated across consecutive windows and has lasted long
238	    //      enough to be an ongoing transfer rather than one spike,
239	    //   4. no job is already in flight for this server.
240	    if (!autoSuspend || severity !== "HIGH") continue;
241	    if (breaches < AUTOSUSPEND_MIN_BREACHES) continue;
242	    if (now.getTime() - firstBreachAt.getTime() < AUTOSUSPEND_MIN_SUSTAIN_MS) continue;
243	    if (
244	      lastBreachAt !== null &&
245	      now.getTime() - lastBreachAt.getTime() > AUTOSUSPEND_MAX_BREACH_GAP_MS
246	    ) {
247	      continue; // not contiguous — separate incidents, leave them to a human
248	    }
249	
250	    const pending = await db.job.count({
251	      where: { serverId: s.id, status: { in: ["QUEUED", "RUNNING"] } },
252	    });
253	    if (pending > 0) continue;
