263	      where: { id: s.id },
264	      data: {
265	        suspendReason: "ABUSE",
266	        suspendedNote: "suspended pending an abuse review — contact support",
267	      },
268	    });
269	    await db.job.create({ data: { type: "SUSPEND", serverId: s.id } });
270	    await db.abuseAlert.updateMany({
271	      where: { serverId: s.id, kind: "BANDWIDTH_SPIKE", status: "OPEN" },
