276	    await db.auditLog.create({
277	      data: {
278	        action: "abuse.autosuspend",
279	        detail:
280	          `${s.hostname} auto-suspended after ${breaches} consecutive outbound-spike windows ` +
281	          `(~${mbps.toFixed(0)} Mbps, threshold ${thresholdMbps} Mbps, abuse_autosuspend=true).`,
