// ---------------------------------------------------------------------------
// VM lifecycle: destroying a VM that may or may not still be there
// ---------------------------------------------------------------------------

/**
 * Is this Proxmox error specifically "vmid <n> is not on this node"?
 *
 * PVE answers a GET/DELETE for an unknown vmid with HTTP 500 and the body
 *   Configuration file 'nodes/<node>/qemu-server/<vmid>.conf' does not exist
 * (verified by running `qm config 999123` on this host, 2026-07-27).
 *
 * The match is deliberately ANCHORED ON THE VMID rather than on the bare phrase
 * "does not exist". `remove()` in worker/index.ts used to swallow anything whose
 * message contained that phrase, which also matches errors that mean the exact
 * opposite of "the VM is gone" — `storage 'vmdata' does not exist`, `volume ...
 * does not exist`, `snapshot 'x' does not exist`. Any of those would have let the
 * DELETE handler decide the VM had been destroyed, drop the Server row and every
 * Volume row pinned to it, and leave a live VM running on the hypervisor with no
 * database record: unbilled, unmanageable and still holding customer data.
 */
export function isVmAbsentError(e: unknown, vmid: number): boolean {
  const err = e as { body?: unknown; message?: unknown } | null | undefined;
  const msg = `${err?.body ?? ""} ${err?.message ?? (typeof e === "string" ? e : "")}`;
  if (!Number.isInteger(vmid)) return false;
  return (
    new RegExp(`qemu-server[/\\\\]${vmid}\\.conf'?\\s+does not exist`, "i").test(msg) ||
    new RegExp(`\\bVM\\s+${vmid}\\s+does not exist\\b`, "i").test(msg) ||
    new RegExp(`\\bno such vm\\b.*\\b${vmid}\\b`, "i").test(msg)
  );
}

/**
 * The side-effectful half of a VM teardown, behind a seam so the decision ladder
 * in `destroyVmIdempotent` can be exercised without a hypervisor.
 * `test/vm-lifecycle.test.ts` drives it with an in-memory fake.
 */
export type VmDestroyHost = {
  /** Ground truth from the hypervisor. "unknown" when it could not be read — never a guess. */
  probe: (vmid: number) => Promise<"present" | "absent" | "unknown">;
  /** Best-effort stop; may reject if the VM is already stopped or gone. */
  stop: (vmid: number) => Promise<void>;
  /** The destructive call. */
  destroy: (vmid: number) => Promise<void>;
};

export type DestroyOutcome = {
  /** True when THIS call issued the destroy and the VM is verified gone afterwards. */
  destroyed: boolean;
  /** True when the VM was already absent, so no destructive call was issued. */
  alreadyAbsent: boolean;
  detail: string;
};

/**
 * Destroy a VM in a way that is SAFE TO RUN TWICE, and that never claims a
 * teardown it did not observe.
 *
 * INCIDENT (found in audit, 2026-07-27 — worker/index.ts `reinstall`): REINSTALL
 * is destroy-then-provision, and the worker retries a failed job up to
 * MAX_ATTEMPTS times. `destroyVm` issued `DELETE /qemu/<vmid>` unconditionally
 * and did not tolerate the VM already being gone. So when attempt 1 destroyed the
 * VM and then failed anywhere in the re-provision that follows (a snippet write,
 * a clone timeout, a config POST), attempts 2 and 3 both died on the very first
 * step — `Configuration file '…/<vmid>.conf' does not exist` — and never reached
 * the provision that was supposed to rebuild the machine. The job ended FAILED,
 * REINSTALL is in VM_STATE_FAILURE_JOBS so the server was flipped to ERROR, and
 * the customer was left with no VM at all: the retry mechanism itself converted a
 * recoverable mid-reinstall failure into permanent destruction. `remove()` in the
 * same file already tolerated the absent case, which is what made the omission
 * here an oversight rather than a policy.
 *
 * The ladder:
 *   1. PROBE FIRST. An absent VM means there is nothing to destroy — return
 *      without issuing any destructive call at all.
 *   2. "unknown" does NOT block the destroy (the caller has already decided this
 *      vmid is to be torn down, and the vmid is not in question), but it is
 *      carried into the detail so nothing downstream reads it as a clean run.
 *   3. TOLERATE a vmid-anchored absent error from the destroy itself — that is
 *      the retry racing a previous attempt that actually succeeded.
 *   4. VERIFY AFTER. Re-probe; if the VM is still present the destroy did not
 *      happen and we throw, rather than let a caller delete the database rows
 *      that are the only remaining handle on a live machine.
 */
export async function destroyVmIdempotent(
  host: VmDestroyHost,
  vmid: number
): Promise<DestroyOutcome> {
  const beforeState = await host.probe(vmid);
  if (beforeState === "absent") {
    return {
      destroyed: false,
      alreadyAbsent: true,
      detail: `VM ${vmid} was already absent — no destroy was issued`,
    };
  }

  // Stop first. A stop failure is not fatal: the VM may already be stopped, and a
  // real blocker (a config lock, a running backup) will surface on the destroy.
  try {
    await host.stop(vmid);
  } catch {
    /* already stopped, or gone — the destroy below is the authority */
  }

  try {
    await host.destroy(vmid);
  } catch (e) {
    if (!isVmAbsentError(e, vmid)) throw e;
    return {
      destroyed: false,
      alreadyAbsent: true,
      detail: `VM ${vmid} disappeared before the destroy landed — treating as already torn down`,
    };
  }

  // Never report a teardown we did not observe.
  const afterState = await host.probe(vmid);
  if (afterState === "present") {
    throw new Error(
      `destroy of VM ${vmid} reported success but the VM is still present on the hypervisor — ` +
        `refusing to continue, because the caller would delete the only records that still point at it.`
    );
  }
  return {
    destroyed: true,
    alreadyAbsent: false,
    detail:
      afterState === "absent"
        ? `VM ${vmid} destroyed and verified gone`
        : `VM ${vmid} destroy completed, but its post-destroy state could not be read back`,
  };
}

// ---------------------------------------------------------------------------
// VMID reuse: the previous tenant's backups
// ---------------------------------------------------------------------------

/**
 * Choose a vmid for a NEW server, skipping any id whose backup archives are
 * still sitting in the shared `backup` storage.
 *
 * INCIDENT (found in audit, 2026-07-27): nothing ever removed a destroyed
 * server's vzdump archives. `remove()` purges the VM and deletes the Server row,
 * but `backup:backup/vzdump-qemu-<vmid>-*.vma.zst` survives indefinitely. PVE's
 * `/cluster/nextid` hands out the LOWEST free id, so the next server deployed
 * after a deletion lands on the freed vmid — and every surface that reasons about
 * backups keys on the vmid alone:
 *
 *   - `listBackups(vmid)` (this file) filters on `b.vmid === vmid`, so the new
 *     owner's Backups tab lists the previous tenant's archives as their own;
 *   - `requestRestore` in lib/actions-server-ops.ts validates the requested volid
 *     against that same listing, so it ACCEPTS them — one click restores a
 *     stranger's entire root filesystem onto the new customer's VM, handing them
 *     that tenant's databases, application secrets, SSH keys and /etc/shadow;
 *   - `pruneBackups` (this file) then counts those archives as the new owner's
 *     and DELETES the previous tenant's data to enforce keep-last-2.
 *
 * Live on this host today (read-only `pvesm list backup`, 2026-07-27): vmids
 * 100–104 and 8000 all hold archives while `/cluster/nextid` answers 105 — so a
 * single delete followed by a single deploy is all it takes.
 *
 * This is the NON-DESTRUCTIVE half of the fix: skip the id, delete nothing.
 * Deciding whether a terminated customer's archives should be reaped (and after
 * how long) is a data-retention policy call, not an audit call.
 *
 * Pure and total: no I/O, no clock. `candidate` is the hypervisor's suggestion,
 * `takenVmids` the ids already in use, `archivedVmids` the ids that still own
 * archives. Returns the first id at or above `candidate` that is in neither set.
 */
export function pickProvisionVmid(opts: {
  candidate: number;
  takenVmids: ReadonlySet<number>;
  archivedVmids: ReadonlySet<number>;
  maxProbe?: number;
}): { vmid: number; skipped: number[] } {
  const { candidate, takenVmids, archivedVmids } = opts;
  const maxProbe = opts.maxProbe ?? 512;
  if (!Number.isInteger(candidate) || candidate <= 0) {
    throw new Error(`pickProvisionVmid: '${candidate}' is not a usable vmid`);
  }
  const skipped: number[] = [];
  for (let id = candidate; id < candidate + maxProbe; id++) {
    if (takenVmids.has(id) || archivedVmids.has(id)) {
      skipped.push(id);
      continue;
    }
    return { vmid: id, skipped };
  }
  throw new Error(
    `no vmid free of stale backup archives in [${candidate}, ${candidate + maxProbe}). ` +
      `Reap the orphaned archives in the "backup" storage (pvesm list backup) before deploying — ` +
      `reusing one of these ids would show the new customer the previous tenant's backups.`
  );
}

/** Every vmid that still owns an archive in the `backup` storage, via a node-scoped client. */
export async function archivedVmids(client: TaskClient): Promise<Set<number>> {
  const content: StorageBackupEntry[] = await client.get(
    `/nodes/${client.node}/storage/backup/content`,
    { content: "backup" }
  );
  const out = new Set<number>();
  for (const b of content ?? []) {
    if (typeof b?.vmid === "number" && Number.isInteger(b.vmid)) out.add(b.vmid);
  }
  return out;
}

export async function pruneBackups(client: any, vmid: number, keep: number): Promise<number> {
  // `keep` decides how many of a customer's restore points survive, so it is
  // validated rather than trusted. `mine.slice(Math.max(0, keep))` looks safe and
  // is not: Math.max(0, NaN) is NaN, Array.slice(NaN) coerces to slice(0), and the
  // delete set silently becomes EVERY backup the customer has. A keep that arrived
  // as undefined, "" or a bad Settings parse would wipe the lot with no error on
  // the way past. Fail closed instead — an over-retained archive costs disk, a
  // missing one costs the customer their only restore point.
  if (!Number.isInteger(keep) || keep < 1) {
    throw new Error(
      `pruneBackups: refusing to prune vmid ${vmid} with keep='${keep}' — ` +
        `retention must be a whole number of at least 1.`
    );
  }

  const registry = await protectedVolids();

