if (!SANDBOX && server.vmid) {
  // `destroyVm` is now idempotent and VERIFIES the VM is gone before returning,
  // so the absent case no longer needs to be caught here at all. The catch that
  // remains is narrowed to this vmid: it used to swallow any error containing
  // "does not exist", which also matches `storage 'vmdata' does not exist` and
  // `volume ... does not exist` — errors that mean the VM is very much still
  // running. On one of those the handler proceeded to delete the Server row and
  // every Volume row pinned to it, leaving a live VM with no database record:
  // invisible to billing, invisible to the panel, still holding the customer's
  // data and impossible to reach through any surface we own.
  try {
    await destroyVm(conn, server.vmid);
  } catch (e: any) {
    if (!isVmAbsentError(e, server.vmid)) throw e;
  }

// Pick a vmid that does NOT still own a previous tenant's backup archives.
// `/cluster/nextid` hands back the lowest FREE id, and nothing reaps a deleted
// server's vzdump archives, so the id freed by a deletion comes back carrying
// the old owner's backups — which every backup surface then attributes to the
// new customer (listBackups/requestRestore key on vmid alone). See
// `pickProvisionVmid` in lib/proxmox.ts. Only for a FRESH allocation: a retry
// keeps the vmid already persisted on the row.
const vmid = server.vmid ?? (await allocateFreshVmid(conn));
const password = generatePassword();

const SNIPPET_DIR = process.env.NXEON_SNIPPET_DIR ?? "/tank/backup/snippets";
const SNIPPET_STORAGE = process.env.NXEON_SNIPPET_STORAGE ?? "backup";

/**
 * Allocate a vmid for a brand-new server, refusing any id that still owns backup
 * archives from a previous tenant (see `pickProvisionVmid` for the incident).
 *
 * If the archive listing cannot be read we do NOT silently fall back to the raw
 * `nextVmid()` — that is the exact behaviour that leaks a previous tenant's data,
 * and a provision that fails is recoverable while a cross-tenant disclosure is
 * not. The job retries; an operator sees why.
 */
async function allocateFreshVmid(conn: any): Promise<number> {
  const candidate = await conn.nextVmid();
  const archived = await archivedVmids(conn);

  // Ids already in use, so skipping forward cannot land on a live VM. Read
  // cluster-wide (qemu + lxc); fall back to this node's qemu list.
  let taken = new Set<number>();
  try {
    const res: any[] = await conn.get("/cluster/resources", { type: "vm" });
    for (const r of res ?? []) if (Number.isInteger(r?.vmid)) taken.add(r.vmid);
  } catch {
    const vms: any[] = await conn.get(`/nodes/${conn.node}/qemu`);
    taken = new Set((vms ?? []).map((v: any) => Number(v?.vmid)).filter(Number.isInteger));
  }

  const { vmid, skipped } = pickProvisionVmid({ candidate, takenVmids: taken, archivedVmids: archived });
  if (skipped.length > 0) {
    console.warn(
      `[worker] vmid ${skipped.join(", ")} skipped for provisioning — still holds backup archives ` +
        `from a previous server; allocated ${vmid} instead`
    );
  }
  return vmid;
}

input.content:
import { test } from "node:test";
import assert from "node:assert/strict";
import {
  destroyVmIdempotent,
  isVmAbsentError,
  pickProvisionVmid,
  pruneBackups,
  type DestroyOutcome,
  type VmDestroyHost,
} from "../lib/proxmox.ts";

/**
 * The VM-teardown and vmid-allocation gate — the decision logic that stands
 * between "the worker retried a job" and a customer permanently losing a machine
 * or being shown a stranger's backups.
 *
 * Every case below is a defect found in the 2026-07-27 audit of the provisioning
 * and server-lifecycle worker. Deterministic: no Proxmox, no SSH, no network, no
 * clock. `destroyVmIdempotent` is driven through its `VmDestroyHost` seam with an
 * in-memory fake hypervisor that records every destructive call it is asked to
 * make, so "did this path issue a destroy?" is an assertion and not a reading of
 * the code.
 */

/* ------------------------------------------------------------------ *
 * 1. "does not exist" is not one error, and the difference is a live VM
 *
 *    worker/index.ts `remove()` swallowed any error whose message contained the
 *    substring "does not exist", on the theory that it meant "the VM was never
 *    created". Proxmox uses that phrase for storages, volumes and snapshots too.
 *    On `storage 'vmdata' does not exist` — a misconfigured or offline storage,
 *    with the VM running perfectly — the handler concluded the teardown had
 *    happened, deleted the Server row and every Volume row pinned to it, and
 *    left a live VM on the hypervisor with no database record: unbilled,
 *    invisible to the panel, still holding the customer's data, and reachable
 *    only by an operator who knows to go looking on the host.
 * ------------------------------------------------------------------ */

/** The exact body PVE returns — captured from `qm config 999123` on this host, 2026-07-27. */
const REAL_ABSENT_BODY =
  "Configuration file 'nodes/ns5002569/qemu-server/999123.conf' does not exist";

test("the real PVE absent-VM error is recognised, anchored on the vmid", () => {
  assert.equal(isVmAbsentError({ body: REAL_ABSENT_BODY }, 999123), true);
  assert.equal(isVmAbsentError(new Error(REAL_ABSENT_BODY), 999123), true);
  assert.equal(isVmAbsentError({ message: "VM 102 does not exist" }, 102), true);

  // Anchored: the SAME message about a DIFFERENT vmid is not proof about ours.
  assert.equal(
    isVmAbsentError({ body: REAL_ABSENT_BODY }, 102),
    false,
    "vmid 102 is not proven absent by an error about vmid 999123",
  );
});

test("a storage/volume/snapshot 'does not exist' is NEVER read as an absent VM", () => {
  // These are the errors that made the old substring match dangerous. Each of
  // them is compatible with the VM being alive and serving customer traffic.
  for (const body of [
    "storage 'vmdata' does not exist",
    "storage 'backup' does not exist",
    "volume 'vmdata:vm-102-disk-1' does not exist",
    "snapshot 'nightly' does not exist",
    "cannot remove image, file does not exist",
  ]) {
    assert.equal(
      isVmAbsentError({ body }, 102),
      false,
      `${body} must not be treated as "VM 102 is gone"`,
    );
    // …and the old logic would have accepted every one of them.
    assert.ok(body.includes("does not exist"), "guard: these all match the old substring test");
  }
});

test("garbage and empty errors are not proof of absence", () => {
  assert.equal(isVmAbsentError(undefined, 102), false);
  assert.equal(isVmAbsentError(null, 102), false);
  assert.equal(isVmAbsentError({}, 102), false);
  assert.equal(isVmAbsentError(new Error("ECONNREFUSED"), 102), false);
  assert.equal(isVmAbsentError({ body: REAL_ABSENT_BODY }, NaN), false, "a non-integer vmid proves nothing");
});

/* ------------------------------------------------------------------ *
 * 2. A retried REINSTALL used to destroy a customer's server for good
 *
 *    REINSTALL is destroy-then-provision, and the worker retries a failed job up
 *    to MAX_ATTEMPTS (3) times. `destroyVm` issued DELETE /qemu/<vmid>
 *    unconditionally and did not tolerate the VM already being gone. So when
 *    attempt 1 destroyed the VM and then failed anywhere in the re-provision that
 *    follows — a cloud-init snippet write, a clone timeout, a config POST —
 *    attempts 2 and 3 both died on the FIRST step with
 *    "Configuration file '…/<vmid>.conf' does not exist" and never reached the
 *    provision that was supposed to rebuild the machine. Job FAILED; REINSTALL is
 *    in VM_STATE_FAILURE_JOBS so the server was flipped to ERROR. The customer
 *    asked for a fresh OS and ended with no VM at all — the retry mechanism
 *    turned a recoverable mid-reinstall failure into permanent destruction.
 *
 *    `remove()` in the same file already tolerated the absent case, which is what
 *    makes the omission an oversight rather than a policy.
 * ------------------------------------------------------------------ */

type FakeHypervisorOpts = {
  /** vmids that exist right now. */
  present?: number[];
  /** Probe cannot be answered (auth failure, node unreachable) — never a guess. */
  probeUnknown?: boolean;
  /** Throw this from destroy() instead of performing it. */
  destroyThrows?: unknown;
  /** Simulate a destroy that reports success but leaves the VM running. */
  destroyIsALie?: boolean;
  stopThrows?: unknown;
};

function fakeHypervisor(opts: FakeHypervisorOpts = {}) {
  const present = new Set(opts.present ?? []);
  const calls: string[] = [];
  const host: VmDestroyHost = {
    probe: async (vmid) => {
      calls.push(`probe ${vmid}`);
      if (opts.probeUnknown) return "unknown";
      return present.has(vmid) ? "present" : "absent";
    },
    stop: async (vmid) => {
      calls.push(`stop ${vmid}`);
      if (opts.stopThrows) throw opts.stopThrows;
    },
    destroy: async (vmid) => {
      calls.push(`destroy ${vmid}`);
      if (opts.destroyThrows) throw opts.destroyThrows;
      if (!opts.destroyIsALie) present.delete(vmid);
    },
  };
  return { host, calls, present };
}

test("destroying an already-absent VM issues NO destructive call and succeeds", async () => {
  // This is the retried-REINSTALL case: attempt 1 destroyed the VM, attempt 2
  // must be able to walk straight past the teardown and get on with rebuilding.
  const f = fakeHypervisor({ present: [] });
  const out = await destroyVmIdempotent(f.host, 102);

  assert.equal(out.alreadyAbsent, true);
  assert.equal(out.destroyed, false);
  assert.match(out.detail, /already absent/);
  assert.deepEqual(f.calls, ["probe 102"], "no stop and no destroy may be issued for an absent VM");
});

test("a destroy racing a previous successful attempt is tolerated, not fatal", async () => {
  // The VM was present at probe time and vanished before the DELETE landed —
  // two attempts overlapping. Tolerated ONLY because the error is vmid-anchored.
  const f = fakeHypervisor({
    present: [102],
    destroyThrows: { body: "Configuration file 'nodes/pve/qemu-server/102.conf' does not exist" },
  });
  const out = await destroyVmIdempotent(f.host, 102);
  assert.equal(out.alreadyAbsent, true);
  assert.match(out.detail, /disappeared before the destroy landed/);
});

test("a destroy that fails for any OTHER reason still throws", async () => {
  // A config lock, a running backup, an auth failure: the VM is still there and
  // the caller must NOT go on to delete the rows that point at it.
  for (const err of [
    { body: "VM is locked (backup)" },
    { body: "storage 'vmdata' does not exist" },
    new Error("401 authentication failure"),
  ]) {
    const f = fakeHypervisor({ present: [102], destroyThrows: err });
    await assert.rejects(() => destroyVmIdempotent(f.host, 102));
  }
});

test("a destroy that reports success but leaves the VM running is rejected", async () => {
  // The rule this codebase is organised around: a surface must never report an
  // outcome it did not verify. `remove()` deletes the Server row and every
  // Volume row on the strength of this call returning, so the post-destroy probe
  // is the only thing standing between a Proxmox no-op and an orphaned live VM.
  const f = fakeHypervisor({ present: [102], destroyIsALie: true });
  await assert.rejects(
    () => destroyVmIdempotent(f.host, 102),
    /still present on the hypervisor/,
  );
  assert.ok(f.calls.includes("destroy 102"));
  assert.equal(f.calls.filter((c) => c === "probe 102").length, 2, "probed before AND after");
});

test("a healthy teardown stops, destroys, and verifies", async () => {
  const f = fakeHypervisor({ present: [102] });
  const out: DestroyOutcome = await destroyVmIdempotent(f.host, 102);
  assert.equal(out.destroyed, true);
  assert.equal(out.alreadyAbsent, false);
  assert.match(out.detail, /verified gone/);
  assert.deepEqual(f.calls, ["probe 102", "stop 102", "destroy 102", "probe 102"]);
});

test("a stop failure never blocks the teardown — the destroy is the authority", async () => {
  // A VM that is already stopped rejects the stop call. That must not strand a
  // deletion the customer asked for.
  const f = fakeHypervisor({ present: [102], stopThrows: new Error("VM 102 not running") });
  const out = await destroyVmIdempotent(f.host, 102);
  assert.equal(out.destroyed, true);
});

test("an unreadable probe does not block a teardown, and is not reported as clean", async () => {
  // "unknown" must not be laundered into either "already gone" (which would skip
  // a destroy the customer asked for) or "verified gone" (which would be a claim
  // we did not observe).
  const f = fakeHypervisor({ present: [102], probeUnknown: true });
  const out = await destroyVmIdempotent(f.host, 102);
  assert.equal(out.alreadyAbsent, false);
  assert.equal(out.destroyed, true);
  assert.match(out.detail, /could not be read back/);
  assert.ok(f.calls.includes("destroy 102"));
});

/* ------------------------------------------------------------------ *
 * 3. A recycled vmid hands the next customer the previous tenant's backups
 *
 *    Nothing reaps a destroyed server's vzdump archives: `remove()` purges the VM
 *    and deletes the Server row, but backup:backup/vzdump-qemu-<vmid>-*.vma.zst
 *    survives indefinitely. PVE's /cluster/nextid returns the LOWEST FREE id, so
 *    the next deploy after a deletion lands on the freed vmid — and every backup
 *    surface keys on the vmid alone:
 *      - listBackups(vmid) filters on b.vmid === vmid, so the new owner's Backups
 *        tab lists the previous tenant's archives as their own;
 *      - requestRestore validates the requested volid against that same listing,
 *        so it ACCEPTS them: one click restores a stranger's entire root
 *        filesystem — their databases, app secrets, SSH keys, /etc/shadow;
 *      - pruneBackups then counts them as the new owner's and DELETES them to
 *        enforce keep-last-2.
 *
 *    Live on this host (read-only `pvesm list backup`, 2026-07-27): vmids 100-104
 *    and 8000 all hold archives while /cluster/nextid answers 105. One delete and
 *    one deploy is the whole exploit.
 * ------------------------------------------------------------------ */

test("a vmid whose previous tenant's archives are still in storage is skipped", () => {
  // vmid 103 was deleted; its archive vzdump-qemu-103-2026_07_26-04_34_19 is
  // still in the backup storage. /cluster/nextid offers 103 to the next customer.
  const r = pickProvisionVmid({
    candidate: 103,
    takenVmids: new Set([100, 101, 102, 104]),
    archivedVmids: new Set([100, 101, 102, 103, 104, 8000]),
  });
  assert.equal(r.vmid, 105, "103 and 104 are unusable; 105 is the first clean id");
  assert.deepEqual(r.skipped, [103, 104]);
});

test("a clean candidate is returned untouched", () => {
  const r = pickProvisionVmid({
    candidate: 105,
    takenVmids: new Set([100, 101, 102, 103, 104]),
    archivedVmids: new Set([100, 101, 102, 103, 104]),
  });
  assert.equal(r.vmid, 105);
  assert.deepEqual(r.skipped, []);
});

test("a live VM is never selected even if it has no archives", () => {
  // Skipping forward past archived ids must not land on somebody's running VM.
  const r = pickProvisionVmid({
    candidate: 100,
    takenVmids: new Set([101, 102]),
    archivedVmids: new Set([100]),
  });
  assert.equal(r.vmid, 103);
  assert.deepEqual(r.skipped, [100, 101, 102]);
});

test("exhausting the probe window refuses rather than reusing a dirty vmid", () => {
  // Failing to deploy is recoverable and visible. Handing a customer another
  // tenant's backups is neither.
  const archived = new Set<number>();
  for (let i = 100; i < 200; i++) archived.add(i);
  assert.throws(
    () =>
      pickProvisionVmid({
        candidate: 100,
        takenVmids: new Set(),
        archivedVmids: archived,
        maxProbe: 50,
      }),
    /no vmid free of stale backup archives/,
  );
});

test("a nonsense candidate is refused rather than coerced", () => {
  for (const candidate of [0, -1, NaN, 1.5]) {
    assert.throws(
      () => pickProvisionVmid({ candidate, takenVmids: new Set(), archivedVmids: new Set() }),
      /not a usable vmid/,
      `candidate=${candidate}`,
    );
  }
});

/* ------------------------------------------------------------------ *
 * 4. Retention with a broken `keep` deletes every backup the customer has
 *
 *    pruneBackups selected its victims with `mine.slice(Math.max(0, keep))`.
 *    That reads as "keep at least none", but Math.max(0, NaN) is NaN and
 *    Array.prototype.slice(NaN) coerces the index to 0 — so the delete set
 *    silently becomes the customer's ENTIRE backup history. A `keep` that arrived
 *    as undefined, "" or a bad Settings parse would wipe the lot with no error on
 *    the way past, and pruneBackups runs automatically after every backup.
 *
 *    Retention is now validated BEFORE anything is read or deleted, so a bad
 *    value cannot even reach the hypervisor.
 * ------------------------------------------------------------------ */

/** A client that fails the test if retention ever reaches the hypervisor with a bad keep. */
function forbiddenClient() {
  return {
    node: "pve",
    get: async () => assert.fail("pruneBackups must not read the hypervisor with an invalid keep"),
    del: async () => assert.fail("pruneBackups must not DELETE anything with an invalid keep"),
  };
}

test("a non-numeric retention refuses before reading or deleting anything", async () => {
  for (const keep of [NaN, undefined, null, "", "two"] as unknown[]) {
    await assert.rejects(
      () => pruneBackups(forbiddenClient(), 102, keep as number),
      /retention must be a whole number of at least 1/,
      `keep=${String(keep)}`,
    );
  }
});

test("keep=0 is refused — retention must never mean 'delete everything'", async () => {
  // Distinct from the NaN case: 0 is a *plausible* config value and would have
  // been accepted by Math.max(0, keep), deleting every archive the customer owns.
  await assert.rejects(
    () => pruneBackups(forbiddenClient(), 102, 0),
    /retention must be a whole number of at least 1/,
  );
  await assert.rejects(() => pruneBackups(forbiddenClient(), 102, -3), /at least 1/);
  await assert.rejects(() => pruneBackups(forbiddenClient(), 102, 1.5), /whole number/);
});

